    /// <summary>
    /// TNA Solve's self-weight chin and its fenced warning, rule 2.5 of
    /// the 2026-09-04 design.
    ///
    /// What went wrong before it: the canvas carried the line "Natural
    /// selfweight frozen 0" on a solve whose self-weight was live, which
    /// is a guard reporting itself OFF in words that read as a safety
    /// measure engaged. The replacement has to say what actually
    /// happened, so the numbers here are the worker's own and the check
    /// drives the component's own formatter rather than reciting it.
    ///
    /// A solve that ran no refinement gets NO line at all. That is the
    /// half worth guarding: a formatter that defaulted its way to
    /// "settled in 1 round" would be the old defect wearing new words.
    /// </summary>
    /// <summary>
    /// Rule 2.4 of the 2026-09-04 selfweight design, on the native side:
    /// the load case that carries a self-weight AND the point loads
    /// riding beside it, and the two numbers that weight is made of.
    ///
    /// Three things are pinned here and each was a hole. The
    /// distribution "self_weight" is the ONLY one that may carry a base
    /// vector and node IDs at once, because it is the only one that
    /// means two loads: "tributary_area" keeps refusing targets exactly
    /// as it did, so nothing authored the old way changes meaning. The
    /// density is a magnitude and a signed one is refused at the
    /// contract, since the base vector already says which way the weight
    /// acts and a negative density would silently invert a vault. And
    /// the two numbers must cross the worker boundary under the names
    /// the python decoder allowlists: it refuses a field it does not
    /// know, so a rename on this side is a dead canvas, not a quiet
    /// default.
    /// </summary>
    private static void ValidateSelfweightLoadCase(Assembly plugin)
    {
        Type loadCaseType = RequireContractType(plugin, "LoadCaseDto");
        string hash = new string('0', 64);

        string LoadCaseJson(string body) =>
            "{\n  \"schemaVersion\": \"0.2\",\n" +
            "  \"kind\": \"ananke.load_case\",\n" +
            $"  \"topologyHash\": \"{hash}\",\n" +
            "  \"name\": \"selfweight-smoke\",\n" +
            body +
            "\n}";

        // The both-wired canvas: a self-weight over the whole pattern and
        // one point load on node 3.
        object both = DeserializeContract(
            plugin,
            loadCaseType,
            LoadCaseJson(
                "  \"distribution\": \"self_weight\",\n" +
                "  \"baseVector\": {\"x\": 0.0, \"y\": 0.0, \"z\": -1.0},\n" +
                "  \"nodeIds\": [3],\n" +
                "  \"vectors\": [{\"x\": 0.0, \"y\": 0.0, \"z\": -25.0}],\n" +
                "  \"thickness\": 0.2,\n" +
                "  \"density\": 24.0"));
        RequireNoValidationErrors(
            both,
            "A self_weight load case carrying a base vector and point loads");

        // A self-weight IS its base vector. Without one there is nothing
        // to weigh the surface with.
        RequireValidationErrors(
            DeserializeContract(
                plugin,
                loadCaseType,
                LoadCaseJson(
                    "  \"distribution\": \"self_weight\",\n" +
                    "  \"thickness\": 0.2,\n" +
                    "  \"density\": 24.0")),
            "A self_weight load case with no base vector");

        // Vectors with nothing to act on are point loads with no nodes.
        RequireValidationErrors(
            DeserializeContract(
                plugin,
                loadCaseType,
                LoadCaseJson(
                    "  \"distribution\": \"self_weight\",\n" +
                    "  \"baseVector\": {\"x\": 0.0, \"y\": 0.0, \"z\": -1.0},\n" +
                    "  \"vectors\": [{\"x\": 0.0, \"y\": 0.0, \"z\": -25.0}]")),
            "A self_weight load case with vectors and no node IDs");

        // The older distribution did not gain the new freedom. This is
        // the half that keeps a definition still authoring
        // "tributary_area" meaning what it always meant.
        RequireValidationErrors(
            DeserializeContract(
                plugin,
                loadCaseType,
                LoadCaseJson(
                    "  \"distribution\": \"tributary_area\",\n" +
                    "  \"baseVector\": {\"x\": 0.0, \"y\": 0.0, \"z\": -1.0},\n" +
                    "  \"nodeIds\": [3],\n" +
                    "  \"vectors\": [{\"x\": 0.0, \"y\": 0.0, \"z\": -25.0}]")),
            "A tributary_area load case carrying explicit node targets");

        // The sign rule, both ways round, and a negative thickness with
        // it: neither is a thing a vault can be made of.
        foreach ((string field, string label) in new[]
        {
            ("  \"density\": -24.0", "a negative density"),
            ("  \"thickness\": -0.2", "a negative thickness")
        })
        {
            RequireValidationErrors(
                DeserializeContract(
                    plugin,
                    loadCaseType,
                    LoadCaseJson(
                        "  \"distribution\": \"self_weight\",\n" +
                        "  \"baseVector\": " +
                        "{\"x\": 0.0, \"y\": 0.0, \"z\": -1.0},\n" +
                        field)),
                $"A self_weight load case with {label}");
        }

        // Absent, both read as one: the load case a definition saved
        // before these two ports existed still sends, and the weight it
        // has always had.
        object bare = DeserializeContract(
            plugin,
            loadCaseType,
            LoadCaseJson(
                "  \"distribution\": \"tributary_area\",\n" +
                "  \"baseVector\": {\"x\": 0.0, \"y\": 0.0, \"z\": -4.0}"));
        RequireNoValidationErrors(bare, "A load case with no selfweight pair");
        foreach (string property in new[] { "Thickness", "Density" })
        {
            object? value = loadCaseType.GetProperty(property)!.GetValue(bare);
            if (value is not double number || number != 1.0)
            {
                throw new InvalidOperationException(
                    $"an absent {property} must read as 1.0, which is the "
                    + "weight an old canvas had; it read "
                    + $"'{value ?? "<null>"}'.");
            }
        }

        // THE WIRE. The python decoder allowlists load-case fields by
        // name and refuses the rest, so these two keys are the contract.
        Type payloads = RequireContractType(plugin, "WorkerPayloads");
        MethodInfo toPayload = payloads
            .GetMethods(BindingFlags.Public | BindingFlags.Static)
            .Single(method =>
                method.Name == "ToWorkerPayload" &&
                method.GetParameters().Length == 1 &&
                method.GetParameters()[0].ParameterType == loadCaseType);
        var payload =
            (IReadOnlyDictionary<string, object?>)toPayload.Invoke(
                null, new[] { both })!;
        foreach ((string key, double expected) in new[]
        {
            ("thickness", 0.2),
            ("density", 24.0)
        })
        {
            if (!payload.TryGetValue(key, out object? sent) ||
                sent is not double number ||
                Math.Abs(number - expected) > 1.0e-12)
            {
                throw new InvalidOperationException(
                    $"the worker payload must carry '{key}' as {expected}; "
                    + $"it carried '{sent ?? "<missing>"}'. The python "
                    + "decoder refuses a field it does not know, so a "
                    + "rename here is a refused solve.");
            }
        }
        // And both halves of the load travel together, or the additive
        // case never reaches the worker at all.
        if (payload["base_vector"] is not double[] { Length: 3 } ||
            payload["node_ids"] is not int[] { Length: 1 } ||
            payload["vectors"] is not Array { Length: 1 })
        {
            throw new InvalidOperationException(
                "a self_weight payload must carry the base vector AND the "
                + "nodal loads beside it; it carried base_vector "
                + $"'{payload["base_vector"] ?? "<missing>"}', node_ids "
                + $"'{payload["node_ids"] ?? "<missing>"}'.");
        }

        Type loads = plugin.GetType(
            "Ananke.COMPAS.Native.Components.LoadsComponent")
            ?? throw new InvalidOperationException(
                "LoadsComponent was not found.");

        // THE EMPTY PORTS, which the whole backwards rule rests on. A
        // Thickness or Density carrying a persistent 1.0 reads as GIVEN
        // on every canvas that ever existed, and every reopened
        // point-load definition would silently start carrying a
        // self-weight. Optional as well, or a blank port colours the
        // component orange for saying nothing.
        object instance = Activator.CreateInstance(loads)!;
        try
        {
            object parameters =
                loads.GetProperty("Params")!.GetValue(instance)!;
            IList inputs = (IList)parameters.GetType()
                .GetProperty("Input")!.GetValue(parameters)!;
            foreach (int slot in new[] { 4, 5 })
            {
                object port = inputs[slot]!;
                string name = (string)port.GetType()
                    .GetProperty("Name")!.GetValue(port)!;
                int stored = (int)port.GetType()
                    .GetProperty("PersistentDataCount")!.GetValue(port)!;
                bool optional = (bool)port.GetType()
                    .GetProperty("Optional")!.GetValue(port)!;
                if (stored != 0 || !optional)
                {
                    throw new InvalidOperationException(
                        $"'{name}' must be OPTIONAL and hold no persistent "
                        + "value: an empty port is how this component "
                        + "tells a canvas that asked for a self-weight "
                        + "from one that never heard of the port. It "
                        + $"holds {stored} value(s), optional {optional}.");
                }
            }
        }
        finally
        {
            (instance as IDisposable)?.Dispose();
        }

        // WHAT THE COMPONENT BUILDS, which is where the backwards rule
        // actually lives. Two of these four cases are definitions saved
        // before the Thickness and Density ports existed, reopened: an
        // append leaves their wires alone and leaves the two new ports
        // EMPTY, and empty is the one thing they cannot counterfeit.
        Type point3 = RequireContractType(plugin, "Point3Dto");
        MethodInfo shape = loads.GetMethod(
            "SelfweightShape",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "LoadsComponent.SelfweightShape was not found.");
        object Vector(double z) =>
            Activator.CreateInstance(point3, 0.0, 0.0, z)!;
        double BaseZ(object result)
        {
            object? vector = result.GetType().GetField("Item2")!
                .GetValue(result);
            return vector is null
                ? double.NaN
                : (double)point3.GetProperty("Z")!.GetValue(vector)!;
        }
        bool SelfWeightOf(object result) =>
            (bool)result.GetType().GetField("Item1")!.GetValue(result)!;

        // An old surface definition: no node IDs, no Thickness, a Vector
        // of (0, 0, -4) that WAS the density. The weight has to stay
        // four, so the Vector is still the base vector.
        object oldSurface = shape.Invoke(
            null, new object[] { Vector(-4.0), 0, false, false })!;
        if (!SelfWeightOf(oldSurface) || BaseZ(oldSurface) != -4.0)
        {
            throw new InvalidOperationException(
                "a surface load with no Thickness or Density must keep the "
                + "Vector as its base vector, or every definition saved "
                + "before those ports silently changes weight; got "
                + $"selfWeight {SelfWeightOf(oldSurface)}, base Z "
                + $"{BaseZ(oldSurface)}.");
        }

        // An old POINT definition, reopened. It never had a self-weight
        // and must not acquire one from two ports it never saw.
        object oldPoint = shape.Invoke(
            null, new object[] { Vector(-25.0), 3, false, false })!;
        if (SelfWeightOf(oldPoint) || !double.IsNaN(BaseZ(oldPoint)))
        {
            throw new InvalidOperationException(
                "point loads with neither Thickness nor Density given "
                + "carry NO self-weight; a reopened point-load definition "
                + "would otherwise gain a vault's weight nobody asked "
                + $"for. Got selfWeight {SelfWeightOf(oldPoint)}.");
        }

        // And the case rule 2.4(b) exists for, reached from either port.
        // The Vector is the point load here, so it cannot also scale the
        // weight: the weight is T x D, straight down.
        foreach ((bool thicknessGiven, bool densityGiven) in new[]
        {
            (true, false),
            (false, true)
        })
        {
            object bothWired = shape.Invoke(
                null,
                new object[] { Vector(-25.0), 3, thicknessGiven, densityGiven })!;
            if (!SelfWeightOf(bothWired) || BaseZ(bothWired) != -1.0)
            {
                throw new InvalidOperationException(
                    "a Thickness or a Density given beside Node IDs asks "
                    + "for a self-weight, and it acts straight down at "
                    + "unit scale rather than being multiplied by a point "
                    + $"load; got selfWeight {SelfWeightOf(bothWired)}, "
                    + $"base Z {BaseZ(bothWired)}.");
            }
        }

        // The chin. A self-weight riding beside point loads has to say so
        // on the component, or the canvas reads "1 node(s)" over a vault
        // carrying its own whole weight.
        MethodInfo summary = loads.GetMethod(
            "LoadSummary",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "LoadsComponent.LoadSummary was not found.");
        foreach ((int nodes, bool selfWeight, string expected) in new[]
        {
            (0, true, "self-weight"),
            (3, true, "self-weight + 3 node(s)"),
            (3, false, "3 node(s)")
        })
        {
            var chin = (string?)summary.Invoke(
                null, new object[] { nodes, selfWeight });
            if (chin != expected)
            {
                throw new InvalidOperationException(
                    $"the chin for {nodes} node(s) with selfWeight "
                    + $"{selfWeight} should read '{expected}'; it read "
                    + $"'{chin ?? "<none>"}'.");
            }
        }
    }

    /// <summary>
    /// THE ARCHIVED WIRE, MEASURED instead of reasoned.
    ///
    /// The compatibility rule for the appended Thickness and Density ports
    /// stands on two claims about a definition saved when Loads had FOUR
    /// inputs: that Grasshopper reattaches its wires by index onto slots 0
    /// to 3, and that slots 4 and 5 come back EMPTY, so
    /// <c>data.GetData(4, ...)</c> returns false and the component knows
    /// nobody asked for a self-weight. Neither claim was exercised. The
    /// nickname pin proves only today's registration, and PersistentDataCount
    /// read off a FRESHLY CONSTRUCTED component proves nothing about a read.
    ///
    /// plugin/definitions/ananke_equilibrium_v01.gh, the one saved definition
    /// in the repository, carries no native Loads component, so there is no
    /// four-input archive of it to read; and a hand-written archive would be
    /// no better, because it is written by the same guesses it would be
    /// checked against. So this makes the archive with GH_IO's OWN writer,
    /// from the component itself with the two appended ports unregistered,
    /// which is exactly the file a canvas saved before those ports existed:
    /// GH_IO writes InputCount 4 by itself and gives each surviving port its
    /// own chunk. Reading that back into a fresh component answers both
    /// claims at once, headless, with Grasshopper serialising at both ends.
    /// It goes red the day GH's param server stops preserving ports the
    /// archive does not mention.
    /// </summary>
    /// <summary>
    /// Loads' Density material list, in two halves, the way this harness
    /// splits every measurement it cannot take whole outside Rhino.
    ///
    /// The FIRST half is the material table itself, pinned as data off the
    /// component's own static field: ten materials, in order, with their
    /// unit weights in kN per cubic metre. Nothing about Grasshopper is
    /// needed to measure that, so nothing about Grasshopper is allowed to
    /// weaken it.
    ///
    /// The SECOND half is the fill, run against real GH_ValueList objects
    /// constructed here. That much DOES work headless, because a value
    /// list's items are plain data; what cannot be measured here is the
    /// canvas event that calls the fill when Param drags a wire onto the
    /// port, and the scheduled solution that follows it. Those two are
    /// Rhino's and they are named in the report as unmeasured.
    /// </summary>
    private static void ValidateDensityMaterialList(Assembly plugin)
    {
        Type loads = plugin.GetType(
            "Ananke.COMPAS.Native.Components.LoadsComponent")
            ?? throw new InvalidOperationException(
                "LoadsComponent was not found.");

        // ---- half one: the table, pinned as data.
        FieldInfo tableField = loads.GetField(
            "DensityMaterials",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "LoadsComponent.DensityMaterials was not found.");
        Array table = (Array)tableField.GetValue(null)!;
        (string Label, double Density)[] expected =
        {
            ("Unit weight (form-finding)", 1.0),
            ("Sandstone", 22.0),
            ("Limestone", 24.0),
            ("Granite", 26.5),
            ("Marble", 27.0),
            ("Brick masonry", 18.5),
            ("Concrete", 24.0),
            ("Reinforced concrete", 25.0),
            ("Rammed earth", 20.0),
            ("Timber (CLT)", 5.5)
        };
        if (table.Length != expected.Length)
        {
            throw new InvalidOperationException(
                $"The Density material table must pin exactly {expected.Length} " +
                $"materials; it holds {table.Length}.");
        }
        for (int i = 0; i < expected.Length; i++)
        {
            object entry = table.GetValue(i)!;
            Type tuple = entry.GetType();
            string label = (string)tuple.GetField("Item1")!.GetValue(entry)!;
            double density = (double)tuple.GetField("Item2")!.GetValue(entry)!;
            if (label != expected[i].Label || density != expected[i].Density)
            {
                throw new InvalidOperationException(
                    $"Density material {i} must pin as (\"{expected[i].Label}\", " +
                    $"{expected[i].Density.ToString("R", CultureInfo.InvariantCulture)}); " +
                    $"found (\"{label}\", " +
                    $"{density.ToString("R", CultureInfo.InvariantCulture)}).");
            }
        }
        // The first entry IS the value an empty port already reads as, which
        // is the whole reason attaching a list is safe.
        {
            object first = table.GetValue(0)!;
            double firstDensity = (double)first.GetType()
                .GetField("Item2")!.GetValue(first)!;
            if (firstDensity != 1.0)
            {
                throw new InvalidOperationException(
                    "The first Density material must be 1.0, the value an " +
                    "empty port reads as, or attaching a value list would " +
                    $"change the weight on its own; it is {firstDensity}.");
            }
        }

        // ---- half two: the fill, against real value lists.
        MethodInfo fill = loads.GetMethod(
            "FillDensityValueList",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "LoadsComponent.FillDensityValueList was not found.");
        // The GH_ValueList type as the PLUGIN binds to it, off the fill's
        // own signature, so this cannot end up exercising one assembly's
        // value list against another's.
        Type valueListType = fill.GetParameters()[0].ParameterType;

        IList Items(object list) =>
            (IList)valueListType.GetProperty("ListItems")!.GetValue(list)!;
        string ItemName(object item) =>
            (string)item.GetType().GetProperty("Name")!.GetValue(item)!;
        string ItemExpression(object item) =>
            (string)item.GetType().GetProperty("Expression")!.GetValue(item)!;
        bool ItemSelected(object item) =>
            (bool)item.GetType().GetProperty("Selected")!.GetValue(item)!;

        object fresh = Activator.CreateInstance(valueListType)
            ?? throw new InvalidOperationException(
                "A GH_ValueList could not be constructed headless.");
        int pristineCount = Items(fresh).Count;
        if (pristineCount == 0)
        {
            throw new InvalidOperationException(
                "A freshly constructed GH_ValueList carries no items here, " +
                "so 'still carries what Grasshopper dropped it with' has " +
                "nothing to mean and the fill cannot tell a new list from " +
                "an emptied one.");
        }

        if (fill.Invoke(null, new[] { fresh }) is not true)
        {
            throw new InvalidOperationException(
                "The fill refused a value list that still carries the " +
                "content Grasshopper gave it, so wiring a fresh list onto " +
                "Density would leave Item1..ItemN standing.");
        }
        IList filled = Items(fresh);
        if (filled.Count != expected.Length)
        {
            throw new InvalidOperationException(
                $"A filled value list must hold exactly {expected.Length} " +
                $"items; it holds {filled.Count}.");
        }
        for (int i = 0; i < expected.Length; i++)
        {
            object item = filled[i]!;
            string wantExpression = expected[i].Density
                .ToString("R", CultureInfo.InvariantCulture);
            if (ItemName(item) != expected[i].Label ||
                ItemExpression(item) != wantExpression)
            {
                throw new InvalidOperationException(
                    $"Filled item {i} must read (\"{expected[i].Label}\", " +
                    $"\"{wantExpression}\"); found (\"{ItemName(item)}\", " +
                    $"\"{ItemExpression(item)}\").");
            }
            // The expression is a BARE number, never a quoted string, so
            // the Number port takes it without a cast standing between.
            if (!double.TryParse(
                    ItemExpression(item),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out double parsed) ||
                parsed != expected[i].Density)
            {
                throw new InvalidOperationException(
                    $"Filled item {i}'s expression must be a bare number a " +
                    "Number port reads directly; it is " +
                    $"\"{ItemExpression(item)}\".");
            }
            bool wantSelected = i == 0;
            if (ItemSelected(item) != wantSelected)
            {
                throw new InvalidOperationException(
                    $"Filled item {i} (\"{expected[i].Label}\") must be " +
                    $"{(wantSelected ? "SELECTED" : "unselected")}: only the " +
                    "scale-free 1.0 is chosen, so attaching a list changes " +
                    "no number until Param picks a material.");
            }
        }

        // A list already filled is not filled again. Without this the fill
        // would reset Param's chosen material on every wiring event.
        if (fill.Invoke(null, new[] { fresh }) is not false)
        {
            throw new InvalidOperationException(
                "The fill ran a SECOND time on a list it had already " +
                "filled, so a chosen material would be reset back to 1.0.");
        }

        // A list the author has edited is left exactly as it stands. Two
        // fixtures, because an edit can change the items' text or their
        // number and either one must stop the fill.
        {
            object renamed = Activator.CreateInstance(valueListType)!;
            object firstItem = Items(renamed)[0]!;
            firstItem.GetType().GetProperty("Name")!
                .SetValue(firstItem, "Param's own");
            if (fill.Invoke(null, new[] { renamed }) is not false)
            {
                throw new InvalidOperationException(
                    "The fill CLOBBERED a value list whose items had been " +
                    "renamed; an edited list is the author's own.");
            }
            IList after = Items(renamed);
            if (after.Count != pristineCount ||
                ItemName(after[0]!) != "Param's own")
            {
                throw new InvalidOperationException(
                    "A renamed value list was refused and then MUTATED " +
                    $"anyway: it holds {after.Count} items and its first " +
                    $"reads \"{ItemName(after[0]!)}\".");
            }
        }
        {
            object shortened = Activator.CreateInstance(valueListType)!;
            IList items = Items(shortened);
            items.RemoveAt(items.Count - 1);
            if (fill.Invoke(null, new[] { shortened }) is not false)
            {
                throw new InvalidOperationException(
                    "The fill CLOBBERED a value list whose items had been " +
                    "added to or removed; an edited list is the author's own.");
            }
            if (Items(shortened).Count != pristineCount - 1)
            {
                throw new InvalidOperationException(
                    "A shortened value list was refused and then MUTATED " +
                    $"anyway: it holds {Items(shortened).Count} items.");
            }
        }

        // ---- and Density is still a bare number.
        object component = Activator.CreateInstance(loads)!;
        try
        {
            object server = loads.GetProperty("Params")!.GetValue(component)!;
            IList inputs = (IList)server.GetType().GetProperty("Input")!
                .GetValue(server)!;
            if (inputs.Count != 6)
            {
                throw new InvalidOperationException(
                    $"LoadsComponent registers {inputs.Count} inputs, not " +
                    "the six this check is written against.");
            }
            object port = inputs[5]!;
            Type portType = port.GetType();
            string PortString(string name) =>
                (string)portType.GetProperty(name)!.GetValue(port)!;
            if (PortString("Name") != "Density" || PortString("NickName") != "D")
            {
                throw new InvalidOperationException(
                    "Input 5 must still be Density / D; it is " +
                    $"{PortString("Name")} / {PortString("NickName")}.");
            }
            if (portType.FullName != "Grasshopper.Kernel.Parameters.Param_Number")
            {
                throw new InvalidOperationException(
                    "Density must stay a plain Number input, not become a " +
                    $"list-shaped port; it is {portType.FullName}.");
            }
            if ((bool)portType.GetProperty("Optional")!.GetValue(port)! is false)
            {
                throw new InvalidOperationException(
                    "Density must stay OPTIONAL: an empty port is the " +
                    "signal that nobody asked for a self-weight.");
            }
            int stored = (int)portType.GetProperty("PersistentDataCount")!
                .GetValue(port)!;
            if (stored != 0)
            {
                throw new InvalidOperationException(
                    "Density must hold NO persistent data, or every archived " +
                    "point-load definition gains a self-weight; it holds " +
                    $"{stored} value(s).");
            }
            if (!PortString("Description").Contains(
                    "value list", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    "Density's description must say that an attached value " +
                    "list fills itself with materials.");
            }

            // And the SUGGEST route stays closed, forever. The shipped
            // Density list arrives through the fresh-placement route
            // alone (a component whose Read never ran, at document-add
            // time); SuggestedValueLists is the wrong door for it,
            // because that mechanism also hangs off the "Create suggested
            // value lists" context menu item, which an author can invoke
            // on an ARCHIVED component, and an archived Density fed a
            // list turns a saved point-load definition into a self-weight
            // one.
            PropertyInfo suggested = loads.GetProperty(
                "SuggestedValueLists",
                BindingFlags.Instance | BindingFlags.NonPublic)
                ?? throw new InvalidOperationException(
                    "SuggestedValueLists was not found on LoadsComponent.");
            IList specs = (IList)suggested.GetValue(component)!;
            if (specs.Count != 0)
            {
                throw new InvalidOperationException(
                    "LoadsComponent must suggest NO value lists, ever: " +
                    "the shipped Density list arrives only through the " +
                    "fresh-placement route, while a SUGGESTED list can " +
                    "also be created from the context menu on an archived " +
                    "component, and a Density that is never empty turns " +
                    "every archived point-load definition into one " +
                    $"carrying a self-weight. It suggests {specs.Count}.");
            }
        }
        finally
        {
            if (component is IDisposable disposable)
                disposable.Dispose();
        }
    }

    /// <summary>
    /// Loads' SHIPPED Density list, the fresh-placement-only rule, in the
    /// halves this harness can take headless.
    ///
    /// The DECISION half is whole. CreatesShippedDensityListOnAdd is the
    /// one gate AddedToDocument obeys, and both of its answers are
    /// measured: a component straight off the palette answers true, and a
    /// component whose Read ran answers false, taken by writing a
    /// component into GH_IO's own archive and reading it back the way a
    /// reopened file or a pasted definition does. The false answer is the
    /// half the rule exists for, because a list auto-wired onto an
    /// archived Density silently puts a self-weight underneath every
    /// saved point-load definition.
    ///
    /// The CONTENT half is whole too. BuildShippedDensityList is the list
    /// AddedToDocument wires in, and it must carry the DensityMaterials
    /// table itself, item for item, through the same fill an attached
    /// list takes, with the scale-free first entry selected and nothing
    /// else.
    ///
    /// The CANVAS half is Rhino's and is named unmeasured: AddObject into
    /// the document, the pivot beside the D port, AddSource onto it.
    /// Those need a live GH_Document, which this harness does not
    /// construct, so the check pins the decision and the content and says
    /// so in its report.
    /// </summary>
    private static void ValidateShippedDensityList(Assembly plugin)
    {
        Type loads = plugin.GetType(
            "Ananke.COMPAS.Native.Components.LoadsComponent")
            ?? throw new InvalidOperationException(
                "LoadsComponent was not found.");

        PropertyInfo decision = loads.GetProperty(
            "CreatesShippedDensityListOnAdd",
            BindingFlags.Instance | BindingFlags.NonPublic)
            ?? throw new InvalidOperationException(
                "LoadsComponent.CreatesShippedDensityListOnAdd was not "
                + "found.");

        // ---- fresh: a component straight off the palette says CREATE.
        object fresh = Activator.CreateInstance(loads)!;
        try
        {
            if (decision.GetValue(fresh) is not true)
            {
                throw new InvalidOperationException(
                    "a freshly constructed Loads must decide to create "
                    + "the shipped Density list at document-add time; it "
                    + "decided not to, so the list would never ship with "
                    + "the component.");
            }
        }
        finally
        {
            if (fresh is IDisposable disposableFresh)
                disposableFresh.Dispose();
        }

        // ---- archived: a component whose Read ran says NOTHING. The
        // archive is written and read through GH_IO's own writer and
        // reader, as the plugin binds to them, exactly the way the
        // archive round trip below takes its measurement.
        MethodInfo read = loads.GetMethods()
            .First(method =>
                method.Name == "Read" &&
                method.GetParameters().Length == 1 &&
                method.GetParameters()[0].ParameterType.Name
                    == "GH_IReader");
        Type readerType = read.GetParameters()[0].ParameterType;
        Type writerType = readerType.Assembly.GetType(
            "GH_IO.Serialization.GH_IWriter", throwOnError: true)!;
        Type archiveType = readerType.Assembly.GetType(
            "GH_IO.Serialization.GH_Archive", throwOnError: true)!;

        object archive = Activator.CreateInstance(archiveType)
            ?? throw new InvalidOperationException(
                "GH_Archive could not be constructed.");
        object saved = Activator.CreateInstance(loads)!;
        object? reopened = null;
        try
        {
            MethodInfo createTop = archiveType.GetMethod(
                "CreateTopLevelNode", new[] { typeof(string) })
                ?? throw new InvalidOperationException(
                    "GH_Archive.CreateTopLevelNode(string) was not found.");
            object writer = createTop.Invoke(
                archive, new object[] { "Container" })
                ?? throw new InvalidOperationException(
                    "GH_Archive gave no writer to save the component into.");
            MethodInfo write = loads.GetMethod("Write", new[] { writerType })
                ?? throw new InvalidOperationException(
                    "LoadsComponent.Write(GH_IWriter) was not found.");
            if (write.Invoke(saved, new[] { writer }) is not true)
            {
                throw new InvalidOperationException(
                    "LoadsComponent refused to write itself into a "
                    + "GH_Archive, so there is no archived component to "
                    + "measure the decision on.");
            }

            object root =
                archiveType.GetProperty("GetRootNode")?.GetValue(archive)
                ?? throw new InvalidOperationException(
                    "GH_Archive.GetRootNode gave nothing to read.");
            object container = root.GetType()
                .GetMethod("FindChunk", new[] { typeof(string) })!
                .Invoke(root, new object[] { "Container" })
                ?? throw new InvalidOperationException(
                    "The archive carries no 'Container' chunk to read the "
                    + "component out of.");

            reopened = Activator.CreateInstance(loads)!;
            if (read.Invoke(reopened, new[] { container }) is not true)
            {
                throw new InvalidOperationException(
                    "LoadsComponent refused to read the archive back.");
            }
            if (decision.GetValue(reopened) is not false)
            {
                throw new InvalidOperationException(
                    "a Loads whose Read ran must decide to create NOTHING "
                    + "at document-add time, or every saved point-load "
                    + "definition would reopen with a list feeding its "
                    + "Density and a self-weight underneath its point "
                    + "loads; it decided to create the list.");
            }
        }
        finally
        {
            if (saved is IDisposable disposableSaved)
                disposableSaved.Dispose();
            if (reopened is IDisposable disposableReopened)
                disposableReopened.Dispose();
        }

        // ---- the content: the list AddedToDocument would wire in is the
        // DensityMaterials table itself, first entry selected. Compared
        // against the component's own static table rather than literals,
        // because the literals are already pinned by the material-list
        // check and pinning them twice would just be two places to edit.
        MethodInfo build = loads.GetMethod(
            "BuildShippedDensityList",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "LoadsComponent.BuildShippedDensityList was not found.");
        FieldInfo tableField = loads.GetField(
            "DensityMaterials",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "LoadsComponent.DensityMaterials was not found.");
        Array table = (Array)tableField.GetValue(null)!;

        object list = build.Invoke(null, null)
            ?? throw new InvalidOperationException(
                "BuildShippedDensityList returned nothing.");
        Type valueListType = build.ReturnType;
        string listName = (string)valueListType.GetProperty("Name")!
            .GetValue(list)!;
        if (listName != "Density")
        {
            throw new InvalidOperationException(
                "the shipped list must be named 'Density', so the canvas "
                + $"says what it feeds; it is named '{listName}'.");
        }
        IList items = (IList)valueListType.GetProperty("ListItems")!
            .GetValue(list)!;
        if (items.Count != table.Length)
        {
            throw new InvalidOperationException(
                $"the shipped list must hold all {table.Length} materials; "
                + $"it holds {items.Count} item(s), so the build did not go "
                + "through the shared fill.");
        }
        for (int i = 0; i < table.Length; i++)
        {
            object entry = table.GetValue(i)!;
            Type tuple = entry.GetType();
            string label = (string)tuple.GetField("Item1")!.GetValue(entry)!;
            double density = (double)tuple.GetField("Item2")!.GetValue(entry)!;
            object item = items[i]!;
            string name = (string)item.GetType().GetProperty("Name")!
                .GetValue(item)!;
            string expression = (string)item.GetType()
                .GetProperty("Expression")!.GetValue(item)!;
            bool selected = (bool)item.GetType().GetProperty("Selected")!
                .GetValue(item)!;
            if (name != label ||
                !double.TryParse(
                    expression,
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out double parsed) ||
                parsed != density)
            {
                throw new InvalidOperationException(
                    $"shipped item {i} must carry (\"{label}\", {density
                        .ToString("R", CultureInfo.InvariantCulture)}); "
                    + $"found (\"{name}\", \"{expression}\").");
            }
            if (selected != (i == 0))
            {
                throw new InvalidOperationException(
                    $"shipped item {i} (\"{label}\") must be "
                    + $"{(i == 0 ? "SELECTED" : "unselected")}: a fresh "
                    + "Loads reads density 1.0, the value an empty port "
                    + "already reads as, until a material is picked.");
            }
        }
    }

    private static void ValidateLoadsArchiveRoundTrip(Assembly plugin)
    {
        Type loads = plugin.GetType(
            "Ananke.COMPAS.Native.Components.LoadsComponent")
            ?? throw new InvalidOperationException(
                "LoadsComponent was not found.");
        Type identity = RequireComponentType(plugin, "ParameterIdentity");
        MethodInfo archivedNames = RequireStatic(identity, "ArchivedNames");
        // GH_IO as the PLUGIN binds to it, so this cannot end up writing one
        // assembly's archive and reading it back with another's reader.
        Type readerType = archivedNames.GetParameters()[0].ParameterType;
        Type writerType = readerType.Assembly.GetType(
            "GH_IO.Serialization.GH_IWriter", throwOnError: true)!;
        Type archiveType = readerType.Assembly.GetType(
            "GH_IO.Serialization.GH_Archive", throwOnError: true)!;

        IList Inputs(object component)
        {
            object server = loads.GetProperty("Params")!.GetValue(component)!;
            return (IList)server.GetType().GetProperty("Input")!
                .GetValue(server)!;
        }
        string PortName(object port) =>
            (string)port.GetType().GetProperty("Name")!.GetValue(port)!;
        int Stored(object port) =>
            (int)port.GetType().GetProperty("PersistentDataCount")!
                .GetValue(port)!;
        bool IsOptional(object port) =>
            (bool)port.GetType().GetProperty("Optional")!.GetValue(port)!;

        string[] expectedNames =
        {
            "Anchored Pattern", "Vector", "Node IDs", "Factor"
        };
        const double ArchivedFactor = 2.5;

        object archive = Activator.CreateInstance(archiveType)
            ?? throw new InvalidOperationException(
                "GH_Archive could not be constructed.");
        object saved = Activator.CreateInstance(loads)!;
        object? reopened = null;
        try
        {
            IList registered = Inputs(saved);
            if (registered.Count != 6)
            {
                throw new InvalidOperationException(
                    $"LoadsComponent registers {registered.Count} inputs, "
                    + "not the six this round trip is written against.");
            }
            object server = loads.GetProperty("Params")!.GetValue(saved)!;
            MethodInfo unregister = server.GetType().GetMethods()
                .First(method =>
                    method.Name == "UnregisterInputParameter" &&
                    method.GetParameters().Length == 1);
            // Highest index first, or the second removal takes a port that
            // has already slid down into slot 4.
            unregister.Invoke(server, new[] { registered[5] });
            unregister.Invoke(server, new[] { registered[4] });

            // A value on Factor, so the read has something of the archive's
            // OWN to put back: without it this could pass by reading nothing
            // at all and leaving a freshly constructed component alone.
            object factor = Inputs(saved)[3]!;
            MethodInfo setPersistent = factor.GetType().GetMethods()
                .First(method =>
                    method.Name == "SetPersistentData" &&
                    method.GetParameters().Length == 1 &&
                    method.GetParameters()[0].ParameterType
                        == typeof(object[]));
            setPersistent.Invoke(
                factor,
                new object[] { new object[] { ArchivedFactor } });

            MethodInfo createTop = archiveType.GetMethod(
                "CreateTopLevelNode", new[] { typeof(string) })
                ?? throw new InvalidOperationException(
                    "GH_Archive.CreateTopLevelNode(string) was not found.");
            object writer = createTop.Invoke(
                archive, new object[] { "Container" })
                ?? throw new InvalidOperationException(
                    "GH_Archive gave no writer to save the component into.");
            MethodInfo write = loads.GetMethod("Write", new[] { writerType })
                ?? throw new InvalidOperationException(
                    "LoadsComponent.Write(GH_IWriter) was not found.");
            if (write.Invoke(saved, new[] { writer }) is not true)
            {
                throw new InvalidOperationException(
                    "LoadsComponent refused to write itself into a "
                    + "GH_Archive, so there is no archived wire to measure.");
            }

            object root =
                archiveType.GetProperty("GetRootNode")?.GetValue(archive)
                ?? throw new InvalidOperationException(
                    "GH_Archive.GetRootNode gave nothing to read.");
            // GetRootNode is the archive's "Root" node and the top-level
            // node made above hangs off it, exactly as a saved definition's
            // Container hangs off Root > Definition > DefinitionObjects >
            // Object. The Container chunk is the reader a component's Read
            // override is handed, so this is the same place Grasshopper
            // walks to.
            object container = root.GetType()
                .GetMethod("FindChunk", new[] { typeof(string) })!
                .Invoke(root, new object[] { "Container" })
                ?? throw new InvalidOperationException(
                    "The archive carries no 'Container' chunk to read the "
                    + "component out of.");

            // The archive really is the FOUR-input shape, read back through
            // the same ArchivedNames a reopened definition goes through. A
            // six-input file would make everything below vacuous, and a
            // reading that comes back NULL is how this measurement found
            // that ArchivedNames knew only the v0.1 script components'
            // ParameterData shape and nothing about the indexed
            // "param_input" chunks every native component actually writes.
            object names = archivedNames.Invoke(null, new[] { container })
                ?? throw new InvalidOperationException(
                    "ArchivedNames returned nothing.");
            var archivedInputs = names.GetType().GetField("Item1")!
                .GetValue(names) as string?[];
            if (archivedInputs is null || archivedInputs.Length != 4)
            {
                throw new InvalidOperationException(
                    "the archive read back must be a FOUR-input file, or it "
                    + "is not the shape of a definition saved before "
                    + "Thickness and Density; GH_IO wrote "
                    + $"'{archivedInputs?.Length.ToString() ?? "no"}' input "
                    + "chunks.");
            }
            for (int slot = 0; slot < expectedNames.Length; slot++)
            {
                if (!string.Equals(
                        archivedInputs[slot],
                        expectedNames[slot],
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"the archived name at slot {slot} should be "
                        + $"'{expectedNames[slot]}'; the file carries "
                        + $"'{archivedInputs[slot] ?? "<none>"}'.");
                }
            }

            reopened = Activator.CreateInstance(loads)!;
            MethodInfo read = loads.GetMethod("Read", new[] { readerType })
                ?? throw new InvalidOperationException(
                    "LoadsComponent.Read(GH_IReader) was not found.");
            if (read.Invoke(reopened, new[] { container }) is not true)
            {
                throw new InvalidOperationException(
                    "LoadsComponent refused to read the archive back.");
            }

            IList loaded = Inputs(reopened);
            if (loaded.Count != 6)
            {
                throw new InvalidOperationException(
                    "an archive naming four inputs came back on a component "
                    + $"carrying {loaded.Count}: Grasshopper no longer "
                    + "preserves ports the archive does not mention, so an "
                    + "APPEND is not the safe reshape this component's "
                    + "whole backwards rule assumes.");
            }
            for (int slot = 0; slot < expectedNames.Length; slot++)
            {
                if (!string.Equals(
                        PortName(loaded[slot]!),
                        expectedNames[slot],
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"the archived wire on slot {slot} landed on "
                        + $"'{PortName(loaded[slot]!)}' where the file left "
                        + $"it on '{expectedNames[slot]}'. Grasshopper "
                        + "reattaches by index, so a slot that changes "
                        + "meaning silently changes what the canvas solves.");
                }
            }

            object reloadedFactor = loaded[3]!;
            object persistent = reloadedFactor.GetType()
                .GetProperty("PersistentData")!.GetValue(reloadedFactor)!;
            MethodInfo allData = persistent.GetType().GetMethod(
                "AllData", new[] { typeof(bool) })
                ?? throw new InvalidOperationException(
                    "GH_Structure.AllData(bool) was not found.");
            double[] restored = ((IEnumerable)allData.Invoke(
                persistent, new object[] { true })!)
                .Cast<object?>()
                .Where(goo => goo is not null)
                .Select(goo => Convert.ToDouble(
                    goo!.GetType().GetProperty("Value")!.GetValue(goo),
                    CultureInfo.InvariantCulture))
                .ToArray();
            if (!restored.Any(
                    value => Math.Abs(value - ArchivedFactor) <= 1.0e-12))
            {
                throw new InvalidOperationException(
                    $"the archive carried a Factor of {ArchivedFactor} and "
                    + "the reopened component holds "
                    + $"[{string.Join(", ", restored)}]. This read put "
                    + "nothing of the FILE's own back, so it proves nothing "
                    + "about the ports beside it either.");
            }

            // AND THE HALF THE WHOLE RULE RESTS ON. Slots 4 and 5 were never
            // in the file, so they must come back exactly as registered:
            // empty, and optional. A value in either reads as GIVEN, and
            // every point-load definition ever saved would silently start
            // carrying a vault's own weight.
            foreach (int slot in new[] { 4, 5 })
            {
                object port = loaded[slot]!;
                if (Stored(port) != 0 || !IsOptional(port))
                {
                    throw new InvalidOperationException(
                        $"'{PortName(port)}' came back off a four-input "
                        + $"archive holding {Stored(port)} value(s), "
                        + $"optional {IsOptional(port)}. An empty port is "
                        + "the one thing an archived definition cannot "
                        + "counterfeit, and it is how this component tells "
                        + "a canvas that asked for a self-weight from one "
                        + "that never heard of the port.");
                }
            }

            // AND THE SENTENCE THE REOPENED CANVAS IS OWED. The warning is
            // the only thing on a reopened file that says the surface
            // moved, and an append is the one reshape whose wires all
            // survive, so it must say that rather than the harsher
            // check-every-wire close.
            MethodInfo runtimeMessages = loads.GetMethod(
                "RuntimeMessages",
                BindingFlags.Public | BindingFlags.Instance)
                ?? throw new InvalidOperationException(
                    "GH_ActiveObject.RuntimeMessages was not found.");
            Type levelType =
                runtimeMessages.GetParameters()[0].ParameterType;
            object messages = runtimeMessages.Invoke(
                reopened, new[] { Enum.Parse(levelType, "Warning") })!;
            string warnings = string.Join(
                " | ", ((IEnumerable)messages).Cast<object>());
            if (!warnings.Contains("Thickness", StringComparison.Ordinal) ||
                !warnings.Contains("Density", StringComparison.Ordinal) ||
                !warnings.Contains("were appended", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    "a four-input archive must reopen carrying the pure-"
                    + "append Warning naming Thickness and Density, or the "
                    + "one thing that tells a canvas its surface moved says "
                    + $"nothing at all; it said '{warnings}'.");
            }
        }
        finally
        {
            (saved as IDisposable)?.Dispose();
            (reopened as IDisposable)?.Dispose();
        }
    }

    /// <summary>
    /// The station's REQUEST: what actually crosses the worker boundary.
    ///
    /// Two claims are measured here. First, the prepared block the station
    /// sends is byte for byte the prepared block <c>tna.solve</c> already
    /// sends, so the Python decoder that reads one reads the other and the
    /// station inherits a wire shape that is already proven end to end
    /// rather than asserting a new one. Second, the principal lines: they
    /// are a C# annotation that never went to the worker at all, so the
    /// station flattens their runs into node IDs and sends those to be
    /// WATCHED, deduplicated and ordered: two lines crossing at a node
    /// would otherwise have that node counted twice in the chin.
    /// </summary>
    private static void ValidateEquilibratePayload(Assembly plugin)
    {
        Type preparedType = RequireContractType(plugin, "TnaPreparedDto");
        Type loadType = RequireContractType(plugin, "LoadCaseDto");
        Type controlType = RequireContractType(plugin, "TnaControlDto");
        Type topologyType = RequireContractType(plugin, "TopologyDto");
        Type codec = plugin.GetType(
            "Ananke.COMPAS.Native.Components.TnaWorkflowWorkerCodec")
            ?? throw new InvalidOperationException(
                "TnaWorkflowWorkerCodec was not found.");
        MethodInfo equilibrate = codec.GetMethod(
            "EquilibratePayload",
            BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "TnaWorkflowWorkerCodec.EquilibratePayload was not found.");
        MethodInfo staged = codec.GetMethod(
            "StagedSolvePayload",
            BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "TnaWorkflowWorkerCodec.StagedSolvePayload was not found.");

        // A three-vertex faced pattern carrying two principal runs that
        // SHARE a node and arrive out of order, which is what two lines
        // crossing at a node looks like. Out of range is not tested here:
        // TopologyDto refuses a run index that is not a vertex, so the
        // builder's own range filter guards a case the contract has
        // already made unreachable.
        string zeroHash = new string('0', 64);
        string topologyDraft = TopologyJsonTemplate
            .Replace("__HASH__", zeroHash)
            .Replace(
                "\"topologyHash\"",
                "\"principalRuns\": [[2, 0], [0, 1]],\n  "
                + "\"topologyHash\"");
        object draft = DeserializeContract(plugin, topologyType, topologyDraft);
        string topologyHash = ComputeTopologyHash(plugin, draft);
        string topologyJson = topologyDraft.Replace(zeroHash, topologyHash);
        string supportSetJson =
            SupportSetJsonTemplate.Replace("__HASH__", topologyHash);
        string patternJson = TnaPatternJsonTemplate
            .Replace("__TOPOLOGY__", topologyJson)
            .Replace("__SUPPORTS__", supportSetJson);
        string preparedJson = TnaPreparedJsonTemplate
            .Replace("__PATTERN__", patternJson)
            .Replace("__HASH__", topologyHash)
            .Replace("__SUPPORTS__", supportSetJson)
            .Replace("__PREPARED_PATTERN__", TnaPreparedPatternJson)
            .Replace("__FORM_GRAPH__", TnaDiagramGraphJson)
            .Replace("__FORCE_GRAPH__", TnaDiagramGraphJson)
            .Replace("__MAPPINGS__", TnaPreparedMappingsJson);
        object prepared =
            DeserializeContract(plugin, preparedType, preparedJson);
        RequireNoValidationErrors(prepared, "TNA Horizontal payload fixture");

        object payload = equilibrate.Invoke(
            null, new object[] { prepared, 42.5 })
            ?? throw new InvalidOperationException(
                "EquilibratePayload returned null.");
        var map = (IReadOnlyDictionary<string, object?>)payload;
        var expectedKeys = new[] { "prepared", "move", "watched_node_ids" };
        if (map.Count != expectedKeys.Length ||
            expectedKeys.Any(key => !map.ContainsKey(key)))
        {
            throw new InvalidOperationException(
                "the station's request carries exactly the prepared stage, "
                + "the Move and the watch list; it carried "
                + string.Join(", ", map.Keys) + ".");
        }
        if (!Equals(map["move"], 42.5))
        {
            throw new InvalidOperationException(
                $"the Move must cross unchanged; got {map["move"]}.");
        }
        int[] watched = (int[])map["watched_node_ids"]!;
        if (!watched.SequenceEqual(new[] { 0, 1, 2 }))
        {
            throw new InvalidOperationException(
                "the watch list is the principal runs' own nodes, "
                + "deduplicated, in range and in order; got ["
                + string.Join(", ", watched) + "].");
        }

        object load = DeserializeContract(
            plugin,
            loadType,
            LoadCaseJsonTemplate.Replace("__HASH__", topologyHash));
        object control =
            DeserializeContract(plugin, controlType, TnaControlJson);
        object solvePayload = staged.Invoke(
            null, new object[] { prepared, load, control })
            ?? throw new InvalidOperationException(
                "StagedSolvePayload returned null.");
        var solveMap = (IReadOnlyDictionary<string, object?>)solvePayload;
        string stationPrepared = JsonSerializer.Serialize(map["prepared"]);
        string solvePrepared = JsonSerializer.Serialize(solveMap["prepared"]);
        if (stationPrepared != solvePrepared)
        {
            throw new InvalidOperationException(
                "the station sends a DIFFERENT prepared stage from the one "
                + "tna.solve sends, so the worker's decoder is being asked "
                + "to read two shapes where one is proven.");
        }
        if (!stationPrepared.Contains("\"tna_prepared\"",
                StringComparison.Ordinal) ||
            !stationPrepared.Contains("\"form_graph\"",
                StringComparison.Ordinal) ||
            !stationPrepared.Contains("\"edge_force_densities\"",
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "the prepared block must carry the snake_case fields the "
                + "worker decodes; got " + stationPrepared[
                    ..Math.Min(200, stationPrepared.Length)]);
        }
    }

    /// <summary>
    /// TNA Horizontal's chin and its warning, measured through the
    /// component's own two static readers rather than described.
    ///
    /// The chin is the 2026-09-04 ruling word for word: what moved, what
    /// the movement bought, and how many watched principal-line nodes went
    /// with it. Every clause is DROPPED rather than faked when its numbers
    /// are absent, which is the difference between "the tension count could
    /// not be measured" and "there are no tension edges".
    /// </summary>
    private static void ValidateHorizontalStation(Assembly plugin)
    {
        Type component = plugin.GetType(
            "Ananke.COMPAS.Native.Components.TnaHorizontalComponent")
            ?? throw new InvalidOperationException(
                "TnaHorizontalComponent was not found.");
        MethodInfo readMetrics = component.GetMethod(
            "HorizontalMetrics",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "TnaHorizontalComponent.HorizontalMetrics was not found.");
        MethodInfo summary = component.GetMethod(
            "HorizontalSummary",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "TnaHorizontalComponent.HorizontalSummary was not found.");

        IReadOnlyDictionary<string, double> Metrics(
            params (string Key, string Value)[] metadata)
        {
            var map = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach ((string key, string value) in metadata)
                map[key] = value;
            return (IReadOnlyDictionary<string, double>)readMetrics.Invoke(
                null, new object[] { map })!;
        }

        (string Chin, string? Warning, string? Remark) Summarise(
            IReadOnlyDictionary<string, double> metrics)
        {
            object result = summary.Invoke(
                null, new object[] { metrics, "m" })
                ?? throw new InvalidOperationException(
                    "HorizontalSummary returned null.");
            Type tuple = result.GetType();
            return (
                (string)tuple.GetField("Item1")!.GetValue(result)!,
                (string?)tuple.GetField("Item2")!.GetValue(result),
                (string?)tuple.GetField("Item3")!.GetValue(result));
        }

        // The worker's own numbers reach this side as TEXT under the
        // diagnostic_metrics prefix. Booleans arrive as "true"/"false" and
        // must read as one and nought, a key that is not the station's is
        // not the station's, and a value that will not parse is ABSENT
        // rather than nought.
        IReadOnlyDictionary<string, double> parsed = Metrics(
            ("diagnostic_metrics.horizontal_angle_before", "25.5238"),
            ("diagnostic_metrics.horizontal_converged_after", "true"),
            ("diagnostic_metrics.horizontal_negative_q_before", "30"),
            ("diagnostic_metrics.horizontal_move", "not a number"),
            ("diagnostic_metrics.boundary_support_count", "6"),
            ("metadata.horizontal_angle_before", "999"));
        if (!parsed.TryGetValue("horizontal_angle_before", out double angle) ||
            Math.Abs(angle - 25.5238) > 1e-9)
        {
            throw new InvalidOperationException(
                "the station's angle should read back off the worker "
                + $"metadata; got {(parsed.ContainsKey("horizontal_angle_before") ? angle.ToString(CultureInfo.InvariantCulture) : "<none>")}.");
        }
        if (!parsed.TryGetValue(
                "horizontal_converged_after", out double converged) ||
            converged != 1.0)
        {
            throw new InvalidOperationException(
                "a worker boolean must read as one or nought, not be "
                + "dropped for failing to parse as a number.");
        }
        if (parsed.ContainsKey("horizontal_move"))
        {
            throw new InvalidOperationException(
                "a value that will not parse is absent, never nought: a "
                + "Move of nought and a Move nobody could read are "
                + "different things.");
        }
        if (parsed.ContainsKey("boundary_support_count") ||
            parsed.Count != 3)
        {
            throw new InvalidOperationException(
                "the reader takes the station's own metrics and nothing "
                + $"else; it took {parsed.Count}.");
        }

        // The worked case: the fan-cornered plan of the python fixture,
        // cured at Move 100.
        var full = new Dictionary<string, double>(StringComparer.Ordinal)
        {
            ["horizontal_plan_move_max"] = 1.7042,
            ["horizontal_plan_move_mean"] = 0.15234,
            ["horizontal_angle_before"] = 25.5238,
            ["horizontal_angle_after"] = 0.0219,
            ["horizontal_negative_q_before"] = 30.0,
            ["horizontal_negative_q_after"] = 0.0,
            ["horizontal_watched_node_count"] = 12.0,
            ["horizontal_watched_moved_count"] = 9.0,
            ["horizontal_converged_after"] = 1.0,
            ["horizontal_gate_degrees"] = 5.0
        };
        (string chin, string? warning, string? remark) = Summarise(full);
        const string expected =
            "moved 1.7 m max, 0.152 mean; 30 tension edges and 25.5 "
            + "degrees became 0 and 0.0; 9 principal-line nodes moved";
        if (chin != expected)
        {
            throw new InvalidOperationException(
                $"the chin should read '{expected}'; got '{chin}'.");
        }
        if (warning is not null)
        {
            throw new InvalidOperationException(
                "a Move that passed the gate warns the canvas about "
                + $"nothing; got '{warning}'.");
        }
        if (remark is not null)
        {
            throw new InvalidOperationException(
                "a watch the station measured in full remarks about "
                + $"nothing; got '{remark}'.");
        }

        // A watched node the station could NOT measure is said out loud.
        // Absorbing it into "did not move" would report a node nobody
        // looked at as a node that stayed put, which is the one thing the
        // ruling's watch must never do.
        var unmeasured = new Dictionary<string, double>(
            full, StringComparer.Ordinal)
        {
            ["horizontal_watched_node_count"] = 11.0,
            ["horizontal_watched_unresolved_count"] = 1.0
        };
        (string unmeasuredChin, _, string? unmeasuredRemark) =
            Summarise(unmeasured);
        if (unmeasuredRemark is null ||
            !unmeasuredRemark.Contains(
                "1 watched principal-line node was",
                StringComparison.Ordinal) ||
            !unmeasuredRemark.Contains(
                "could not be measured", StringComparison.Ordinal) ||
            !unmeasuredRemark.Contains("out of 11", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "an unmeasurable watched node must be named, with the "
                + "denominator the moved count is really out of; got "
                + $"'{unmeasuredRemark ?? "<none>"}'.");
        }
        if (unmeasuredChin != expected)
        {
            throw new InvalidOperationException(
                "the remark is a remark, not a rewrite of the chin; got "
                + $"'{unmeasuredChin}'.");
        }
        var unmeasuredPlural = new Dictionary<string, double>(
            unmeasured, StringComparer.Ordinal)
        {
            ["horizontal_watched_unresolved_count"] = 3.0
        };
        if (!Summarise(unmeasuredPlural).Remark!.Contains(
                "3 watched principal-line nodes were",
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "three unmeasurable nodes are nodes, not a node; got "
                + $"'{Summarise(unmeasuredPlural).Remark}'.");
        }
        if (Summarise(new Dictionary<string, double>(
                full, StringComparer.Ordinal)
            {
                ["horizontal_watched_unresolved_count"] = 0.0
            }).Remark is not null)
        {
            throw new InvalidOperationException(
                "nought unmeasurable nodes is nothing to say.");
        }

        // One watched node moved, so the word is singular.
        var single = new Dictionary<string, double>(full, StringComparer.Ordinal)
        {
            ["horizontal_watched_moved_count"] = 1.0
        };
        if (!Summarise(single).Chin.EndsWith(
                "1 principal-line node moved", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "one moved node is a node, not nodes; got "
                + $"'{Summarise(single).Chin}'.");
        }

        // A pattern with no principal lines annotated says NOTHING about
        // them, rather than reporting nought of nought moved; and a tension
        // count the projection could not measure is dropped with it.
        var bare = new Dictionary<string, double>(StringComparer.Ordinal)
        {
            ["horizontal_plan_move_max"] = 1.7042,
            ["horizontal_plan_move_mean"] = 0.15234,
            ["horizontal_angle_before"] = 25.5238,
            ["horizontal_angle_after"] = 0.0219,
            ["horizontal_watched_node_count"] = 0.0,
            ["horizontal_watched_moved_count"] = 0.0,
            ["horizontal_converged_after"] = 1.0
        };
        (string bareChin, string? bareWarning, _) = Summarise(bare);
        if (bareChin !=
            "moved 1.7 m max, 0.152 mean; 25.5 degrees became 0.0")
        {
            throw new InvalidOperationException(
                "with no tension count and no principal lines the chin "
                + $"carries neither clause; got '{bareChin}'.");
        }
        if (bareWarning is not null)
            throw new InvalidOperationException("bare case warned wrongly.");

        // The gate still failing is the one thing the station owes the
        // canvas a sentence about, and the sentence has to say what the
        // author can do next.
        var stalled = new Dictionary<string, double>(full, StringComparer.Ordinal)
        {
            ["horizontal_angle_after"] = 18.75,
            ["horizontal_converged_after"] = 0.0
        };
        (_, string? stalledWarning, _) = Summarise(stalled);
        if (stalledWarning is null ||
            !stalledWarning.Contains("18.8", StringComparison.Ordinal) ||
            !stalledWarning.Contains("5.0", StringComparison.Ordinal) ||
            !stalledWarning.Contains("Raise Move", StringComparison.Ordinal) ||
            !stalledWarning.Contains("half-plane", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "a Move that did not reach the gate must name the angle "
                + "it stalled at, the gate it missed, and what to do; got "
                + $"'{stalledWarning ?? "<none>"}'.");
        }

        // Nothing measured at all is said as nothing measured.
        if (Summarise(
                new Dictionary<string, double>(StringComparer.Ordinal))
            .Chin != "no measurement")
        {
            throw new InvalidOperationException(
                "an empty metric set is no measurement, not an empty chin.");
        }
    }

    /// <summary>
    /// TNA Solve's failed-gate advice names TNA Horizontal.
    ///
    /// The advice used to end at "smooth the pattern or accept the
    /// residual", which named no remedy an author could reach: a plan
    /// whose corners no positive force density can balance is not smoothed
    /// into equilibrium by hand. Advice only, in both modes; nothing here
    /// runs the station.
    /// </summary>
    private static void ValidateReciprocityAdvice(Assembly plugin)
    {
        Type component = plugin.GetType(
            "Ananke.COMPAS.Native.Components.TnaSolveComponent")
            ?? throw new InvalidOperationException(
                "TnaSolveComponent was not found.");
        MethodInfo advice = component.GetMethod(
            "ReciprocityAdvice",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "TnaSolveComponent.ReciprocityAdvice was not found.");

        string Advice(bool autoMode) =>
            (string)advice.Invoke(null, new object[] { autoMode })!;

        foreach (bool autoMode in new[] { true, false })
        {
            string text = Advice(autoMode);
            if (!text.Contains("TNA Horizontal", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"the {(autoMode ? "auto" : "fixed")}-iteration advice "
                    + "must name TNA Horizontal as the remedy; got "
                    + $"'{text}'.");
            }
        }
        if (!Advice(true).Contains(
                "accept the residual", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "the station is named BESIDE accepting the residual, not "
                + "instead of it: an author who wants the residual must "
                + "still be told they may have it.");
        }
        if (!Advice(false).Contains(
                "Raise Iterations", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "a hand-set iteration count still gets its own first "
                + "remedy before the station is offered.");
        }
    }

    private static void ValidateSelfweightSummary(Assembly plugin)
    {
        Type component = plugin.GetType(
            "Ananke.COMPAS.Native.Components.TnaSolveComponent")
            ?? throw new InvalidOperationException(
                "TnaSolveComponent was not found.");
        MethodInfo summary = component.GetMethod(
            "SelfweightSummary",
            BindingFlags.NonPublic | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "TnaSolveComponent.SelfweightSummary was not found.");

        (string? Chin, string? Warning) Run(
            params (string Key, double Value)[] metrics)
        {
            var map = new Dictionary<string, double>(StringComparer.Ordinal);
            foreach ((string key, double value) in metrics)
                map[key] = value;
            object result = summary.Invoke(null, new object[] { map })
                ?? throw new InvalidOperationException(
                    "SelfweightSummary returned null.");
            Type tuple = result.GetType();
            return (
                (string?)tuple.GetField("Item1")!.GetValue(result),
                (string?)tuple.GetField("Item2")!.GetValue(result));
        }

        // A converged refinement: the worker's seven rounds and its
        // 0.0009 drift, read back as rounds and per cent.
        (string? chin, string? warning) = Run(
            ("selfweight_refined", 1.0),
            ("selfweight_rounds_run", 7.0),
            ("selfweight_final_drift", 0.0008999),
            ("selfweight_converged", 1.0),
            ("selfweight_fenced", 0.0));
        if (chin != "self-weight settled in 7 rounds (drift 0.1 per cent)")
        {
            throw new InvalidOperationException(
                "a settled refinement's chin should name its rounds and "
                + $"its drift; got '{chin ?? "<none>"}'.");
        }
        if (warning is not null)
        {
            throw new InvalidOperationException(
                "a settled refinement warns the canvas about nothing; got "
                + $"'{warning}'.");
        }

        // A fenced one. The chin says fenced rather than settled, and the
        // canvas is told in sentences: the rounds, the drift, and which
        // round's weight it is looking at.
        (chin, warning) = Run(
            ("selfweight_refined", 1.0),
            ("selfweight_rounds_run", 10.0),
            ("selfweight_final_drift", 0.0142),
            ("selfweight_converged", 0.0),
            ("selfweight_fenced", 1.0));
        if (chin != "self-weight fenced at 10 rounds (drift 1.4 per cent)")
        {
            throw new InvalidOperationException(
                "a fenced refinement's chin should say fenced and carry "
                + $"its drift; got '{chin ?? "<none>"}'.");
        }
        if (warning is null ||
            !warning.Contains("did not settle in 10 rounds",
                StringComparison.Ordinal) ||
            !warning.Contains("still moving 1.4 per cent",
                StringComparison.Ordinal) ||
            !warning.Contains("round-1 weight", StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "a fenced refinement must name the rounds, the drift and "
                + "the round it fell back to; got "
                + $"'{warning ?? "<none>"}'.");
        }

        // One round, so the word is singular in both places. This is the
        // cap-of-one case the python fence check drives.
        (chin, warning) = Run(
            ("selfweight_refined", 1.0),
            ("selfweight_rounds_run", 1.0),
            ("selfweight_final_drift", 0.3312),
            ("selfweight_converged", 0.0),
            ("selfweight_fenced", 1.0));
        if (chin != "self-weight fenced at 1 round (drift 33.1 per cent)")
        {
            throw new InvalidOperationException(
                $"a one-round fence reads in the singular; got '{chin}'.");
        }
        if (warning is null ||
            !warning.Contains("did not settle in 1 round;",
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "a one-round fence's warning reads in the singular; got "
                + $"'{warning ?? "<none>"}'.");
        }

        // No refinement ran. A natural height freezes its weight at the
        // plan and has no target to refine against, and a canvas with no
        // surface load has no weight at all: neither owes the chin a
        // line, and neither is a fence.
        (chin, warning) = Run(
            ("selfweight_refined", 0.0),
            ("selfweight_rounds_run", 1.0),
            ("selfweight_final_drift", 0.0),
            ("selfweight_converged", 1.0),
            ("selfweight_fenced", 0.0));
        if (chin is not null || warning is not null)
        {
            throw new InvalidOperationException(
                "a solve that ran no refinement should say nothing about "
                + $"one; got chin '{chin ?? "<none>"}' and warning "
                + $"'{warning ?? "<none>"}'.");
        }

        // An older worker, or a solve whose metrics never arrived: the
        // absence of the key is absence, not a refinement of no rounds.
        (chin, warning) = Run(("zmax_solved", 5.0));
        if (chin is not null || warning is not null)
        {
            throw new InvalidOperationException(
                "metrics carrying no self-weight keys should produce no "
                + $"line; got chin '{chin ?? "<none>"}' and warning "
                + $"'{warning ?? "<none>"}'.");
        }

        // The shape the worker actually ships now for a solve that
        // refined nothing: the self-weight MODE, as the numeric twin the
        // canvas can read, and not one key of the loop. A mode of 1,
        // frozen at the plan, is not a refinement of one round, and
        // nothing here may infer one from it.
        (chin, warning) = Run(
            ("selfweight_mode_code", 1.0),
            ("zmax_solved", 5.0));
        if (chin is not null || warning is not null)
        {
            throw new InvalidOperationException(
                "a self-weight mode is not a refinement: metrics carrying "
                + "a mode code and none of the loop's keys should produce "
                + $"no line; got chin '{chin ?? "<none>"}' and warning "
                + $"'{warning ?? "<none>"}'.");
        }
    }

    /// <summary>
    /// The icon family, checked against the components themselves.
    ///
    /// Five of the twenty badges used to be drawn by a different hand, in a
    /// different shape, and the map that owns the rest had sixteen entries
    /// naming components that had been deleted while naming none of the five
    /// that existed. Nothing measured any of that, because nothing connected
    /// the map to the assembly. This does: every component's icon key has
    /// exactly one entry, its category IS the panel the component registers
    /// under, its label is the two letters the spec fixes, its filename is
    /// the key (which is what PluginResources.Icon reads), and the badge's
    /// own pixels carry the category's fill.
    ///
    /// The fill is sampled at (12, 20). The badge is a rounded rectangle
    /// filled edge to edge under a lighter top band of four rows; the label
    /// is two five-by-seven glyphs at scale two, centred, so it occupies
    /// rows 5 to 18 and a shadow row 19, and columns 1 to 22 with a
    /// two-pixel gap between the glyphs. Row 20 is below all of it and
    /// inside the rounded box, so it is the fill and nothing else.
    /// </summary>
    private static void ValidateIconMap(
        Assembly plugin,
        Type[] componentTypes,
        string pluginPath)
    {
        string mapPath = FindIconMap(pluginPath);
        JsonNode map = JsonNode.Parse(File.ReadAllText(mapPath))
            ?? throw new InvalidOperationException(
                $"{mapPath} did not parse as JSON.");
        JsonObject categories = map["categories"]?.AsObject()
            ?? throw new InvalidOperationException(
                "icon-map.json carries no categories.");
        JsonArray native = map["native_components"]?.AsArray()
            ?? throw new InvalidOperationException(
                "icon-map.json carries no native_components.");

        var byKey = new Dictionary<string, JsonNode>(StringComparer.Ordinal);
        foreach (JsonNode? entry in native)
        {
            JsonNode row = entry
                ?? throw new InvalidOperationException(
                    "icon-map.json has a null native_components entry.");
            string key = (string?)row["key"]
                ?? throw new InvalidOperationException(
                    "A native_components entry carries no key.");
            if (!byKey.TryAdd(key, row))
            {
                throw new InvalidOperationException(
                    $"'{key}' has more than one native_components entry, so "
                    + "two entries own one PNG and the last generated wins.");
            }
        }
        if (byKey.Count != componentTypes.Length)
        {
            throw new InvalidOperationException(
                $"{componentTypes.Length} components and {byKey.Count} icons: "
                + "the family covers every component and nothing else, or a "
                + "deleted component's badge stays embedded for ever.");
        }

        foreach (Type componentType in componentTypes)
        {
            string typeName = componentType.FullName ?? componentType.Name;
            if (!NativeIconEntries.TryGetValue(
                    typeName, out (string Key, string Label) expected))
            {
                throw new InvalidOperationException(
                    $"{typeName} has no pinned icon key and label; every "
                    + "component wears one badge from the one family.");
            }
            object instance = Activator.CreateInstance(componentType)
                ?? throw new InvalidOperationException(
                    $"Could not construct {typeName}.");
            try
            {
                string key = IconKeyOf(instance, componentType);
                if (!string.Equals(key, expected.Key, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"{componentType.Name} asks for icon '{key}'; the "
                        + $"family gives it '{expected.Key}'.");
                }
                if (!byKey.TryGetValue(key, out JsonNode? row))
                {
                    throw new InvalidOperationException(
                        $"'{key}' has no native_components entry, so nothing "
                        + "generates that badge and the component wears "
                        + "whatever PNG happens to be lying beside the map.");
                }
                string label = (string?)row["label"] ?? string.Empty;
                if (!string.Equals(label, expected.Label, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"{componentType.Name}'s badge reads '{label}'; the "
                        + $"spec gives it '{expected.Label}'.");
                }
                string filename = (string?)row["filename"] ?? string.Empty;
                if (!string.Equals(filename, key + ".png", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"'{key}' is drawn into '{filename}', but the loader "
                        + $"reads the resource '{key}.png' and would find "
                        + "nothing.");
                }
                string category = (string?)row["category"] ?? string.Empty;
                string subCategory =
                    componentType.GetProperty("SubCategory")?.GetValue(instance)
                        as string
                    ?? string.Empty;
                if (!string.Equals(category, subCategory, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        $"{componentType.Name} sits under '{subCategory}' and "
                        + $"its badge is filled for '{category}': the colour "
                        + "is the panel, so a component that moves tab and "
                        + "keeps its fill lies about where it lives.");
                }
                string fill = (string?)categories[category]?["fill"]
                    ?? throw new InvalidOperationException(
                        $"icon-map.json has no fill for category '{category}'.");
                (int r, int g, int b) = ParseFill(fill);
                (int actualR, int actualG, int actualB) =
                    BadgeFill(RequireIconBitmap(instance, componentType));
                if (r != actualR || g != actualG || b != actualB)
                {
                    throw new InvalidOperationException(
                        $"{componentType.Name}'s badge is filled "
                        + $"#{actualR:X2}{actualG:X2}{actualB:X2} where "
                        + $"'{category}' is {fill}: the PNG on disk is not the "
                        + "one this map describes, so the generator has not "
                        + "been run since the map changed.");
                }
            }
            finally
            {
                if (instance is IDisposable disposable)
                    disposable.Dispose();
            }
        }
    }

    /// <summary>
    /// The icon key a component names to its base constructor, which is also
    /// the embedded resource name and so the file name. Held in a private
    /// field on both native bases, so the walk goes up until it finds one.
    /// </summary>
    private static string IconKeyOf(object instance, Type componentType)
    {
        for (Type? current = componentType;
             current is not null;
             current = current.BaseType)
        {
            FieldInfo? field = current.GetField(
                "_iconName",
                BindingFlags.Instance |
                BindingFlags.NonPublic |
                BindingFlags.DeclaredOnly);
            if (field is null)
                continue;
            return field.GetValue(instance) as string ?? string.Empty;
        }
        throw new InvalidOperationException(
            $"{componentType.Name} carries no icon key; every native "
            + "component names one to its base constructor.");
    }

    /// <summary>
    /// The badge's own fill, read off the embedded bitmap at (12, 20).
    /// Reflected rather than referenced, in this harness's usual manner, so
    /// nothing here has to bind to System.Drawing at compile time.
    /// </summary>
    private static (int R, int G, int B) BadgeFill(object icon)
    {
        MethodInfo getPixel = icon.GetType().GetMethod(
            "GetPixel", new[] { typeof(int), typeof(int) })
            ?? throw new InvalidOperationException(
                "The icon is not a bitmap with pixels to read.");
        object colour = getPixel.Invoke(icon, new object[] { 12, 20 })
            ?? throw new InvalidOperationException(
                "GetPixel returned nothing.");
        Type colourType = colour.GetType();
        int Channel(string name) => Convert.ToInt32(
            colourType.GetProperty(name)?.GetValue(colour));
        return (Channel("R"), Channel("G"), Channel("B"));
    }

    private static (int R, int G, int B) ParseFill(string value)
    {
        if (value.Length != 7 || value[0] != '#')
        {
            throw new InvalidOperationException(
                $"A category fill is #RRGGBB; got '{value}'.");
        }
        return (
            Convert.ToInt32(value.Substring(1, 2), 16),
            Convert.ToInt32(value.Substring(3, 2), 16),
            Convert.ToInt32(value.Substring(5, 2), 16));
    }

    /// <summary>
    /// plugin/icons/icon-map.json, found by walking up from the .gha under
    /// test and then from this harness's own output directory. The map is
    /// the generator's manifest and lives in the repository, not in the
    /// build, so there is nothing to resolve it by but the tree.
    /// </summary>
    private static string FindIconMap(string pluginPath) =>
        FindRepositoryFile(
            pluginPath,
            new[]
            {
                Path.Combine("plugin", "icons", "icon-map.json"),
                Path.Combine("icons", "icon-map.json")
            },
            "plugin/icons/icon-map.json",
            "the icon family is checked against that map");

    /// <summary>
    /// A file that lives in the REPOSITORY rather than in the build, found
    /// by walking up from the plugin under test and then from this harness's
    /// own output directory. Each candidate is a path relative to a
    /// repository root, tried in order at every level.
    /// </summary>
    private static string FindRepositoryFile(
        string pluginPath,
        IReadOnlyList<string> candidates,
        string what,
        string why)
    {
        var starts = new List<string>();
        string? beside = Path.GetDirectoryName(Path.GetFullPath(pluginPath));
        if (beside is not null)
            starts.Add(beside);
        starts.Add(AppContext.BaseDirectory);
        foreach (string start in starts)
        {
            for (DirectoryInfo? directory = new(start);
                 directory is not null;
                 directory = directory.Parent)
            {
                foreach (string candidate in candidates)
                {
                    string full = Path.Combine(directory.FullName, candidate);
                    if (File.Exists(full))
                        return full;
                }
            }
        }
        throw new InvalidOperationException(
            what + " was not found above " +
            string.Join(" or ", starts) +
            "; " + why + ", so it has to be findable from the plugin under "
            + "test.");
    }

    /// <summary>
    /// Constructs the three spine contracts (<c>AnchoredPatternDto</c>,
    /// <c>ProblemDto</c>, <c>RelaxedDto</c>) via JSON round-tripped through
    /// the plugin's own <c>ContractJson</c> codec, exercising one valid and
    /// one invalid case per type, then confirms a <c>ProblemDto</c> attaches
    /// to <c>ResultDto.Problem</c> without breaking a valid TNA result.
    /// </summary>
    private static void ValidateSpineContracts(Assembly plugin)
    {
        Type topologyType = RequireContractType(plugin, "TopologyDto");
        Type anchoredType = RequireContractType(plugin, "AnchoredPatternDto");
        Type problemType = RequireContractType(plugin, "ProblemDto");
        Type preparedType = RequireContractType(plugin, "TnaPreparedDto");
        Type relaxedType = RequireContractType(plugin, "RelaxedDto");
        Type resultType = RequireContractType(plugin, "ResultDto");
        Type equilibriumType = RequireContractType(plugin, "EquilibriumResultDto");
        Type graphType = RequireContractType(plugin, "TnaDiagramGraphDto");

        string zeroHash = new string('0', 64);
        object draftTopology = DeserializeContract(
            plugin,
            topologyType,
            TopologyJsonTemplate.Replace("__HASH__", zeroHash));
        string topologyHash = ComputeTopologyHash(plugin, draftTopology);
        string topologyJson = TopologyJsonTemplate.Replace("__HASH__", topologyHash);
        string supportSetJson =
            SupportSetJsonTemplate.Replace("__HASH__", topologyHash);
        string patternJson = TnaPatternJsonTemplate
            .Replace("__TOPOLOGY__", topologyJson)
            .Replace("__SUPPORTS__", supportSetJson);

        // AnchoredPatternDto: valid (one anchor) and invalid (no anchors).
        string validAnchoredJson = AnchoredPatternJsonTemplate
            .Replace("__PATTERN__", patternJson)
            .Replace("__ANCHORS__", "[0]");
        object validAnchored =
            DeserializeContract(plugin, anchoredType, validAnchoredJson);
        RequireNoValidationErrors(validAnchored, "Valid AnchoredPatternDto");

        object invalidAnchored = DeserializeContract(
            plugin,
            anchoredType,
            AnchoredPatternJsonTemplate
                .Replace("__PATTERN__", patternJson)
                .Replace("__ANCHORS__", "[]"));
        RequireValidationErrors(
            invalidAnchored,
            "Invalid AnchoredPatternDto without anchor node IDs");

        // ProblemDto: valid (matching topology hash) and invalid
        // (load.topologyHash does not match the anchored pattern).
        string validLoadJson = LoadCaseJsonTemplate.Replace("__HASH__", topologyHash);
        string validProblemJson = ProblemJsonTemplate
            .Replace("__ANCHORED__", validAnchoredJson)
            .Replace("__LOAD__", validLoadJson);
        object validProblem =
            DeserializeContract(plugin, problemType, validProblemJson);
        RequireNoValidationErrors(validProblem, "Valid ProblemDto");

        object invalidProblem = DeserializeContract(
            plugin,
            problemType,
            ProblemJsonTemplate
                .Replace("__ANCHORED__", validAnchoredJson)
                .Replace(
                    "__LOAD__",
                    LoadCaseJsonTemplate.Replace("__HASH__", zeroHash)));
        RequireValidationErrors(
            invalidProblem,
            "Invalid ProblemDto with a load from a different source topology");

        // RelaxedDto: valid (both members present and valid) and invalid
        // (both members missing).
        string preparedJson = TnaPreparedJsonTemplate
            .Replace("__PATTERN__", patternJson)
            .Replace("__HASH__", topologyHash)
            .Replace("__SUPPORTS__", supportSetJson)
            .Replace("__PREPARED_PATTERN__", TnaPreparedPatternJson)
            .Replace("__FORM_GRAPH__", TnaDiagramGraphJson)
            .Replace("__FORCE_GRAPH__", TnaDiagramGraphJson)
            .Replace("__MAPPINGS__", TnaPreparedMappingsJson);
        object prepared = DeserializeContract(plugin, preparedType, preparedJson);
        RequireNoValidationErrors(
            prepared,
            "Valid TnaPreparedDto (spine smoke fixture)");

        object validRelaxed = DeserializeContract(
            plugin,
            relaxedType,
            RelaxedJsonTemplate
                .Replace("__PREPARED__", preparedJson)
                .Replace("__PROBLEM__", validProblemJson));
        RequireNoValidationErrors(validRelaxed, "Valid RelaxedDto");

        object invalidRelaxed =
            DeserializeContract(plugin, relaxedType, RelaxedEmptyJson);
        RequireValidationErrors(
            invalidRelaxed,
            "Invalid RelaxedDto missing both prepared and problem");

        // ResultDto.Problem: optional provenance attach (Task 4 step 4)
        // must not disturb an otherwise-valid TNA result.
        object resultWithProblem = CreateResultDto(
            resultType,
            solver: "tna",
            equilibrium: CreateInstance(equilibriumType),
            formGraph: CreateInstance(graphType),
            forceGraph: CreateInstance(graphType));
        SetContractProperty(resultWithProblem, resultType, "Problem", validProblem);
        RequireNoValidationErrors(
            resultWithProblem,
            "Valid TNA ResultDto with an attached Problem");
    }

    private static object DeserializeContract(
        Assembly plugin,
        Type contractType,
        string json)
    {
        Type contractJsonType = RequireContractType(plugin, "ContractJson");
        MethodInfo generic = contractJsonType.GetMethod(
            "Deserialize",
            BindingFlags.Public | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "ContractJson.Deserialize was not found.");
        MethodInfo bound = generic.MakeGenericMethod(contractType);
        return bound.Invoke(null, new object[] { json })
            ?? throw new InvalidOperationException(
                $"Deserializing {contractType.FullName} returned null.");
    }

    private static string ComputeTopologyHash(Assembly plugin, object topology)
    {
        Type fingerprintType = RequireContractType(plugin, "TopologyFingerprint");
        MethodInfo computeMethod = fingerprintType.GetMethod(
            "Compute",
            BindingFlags.Public | BindingFlags.Static)
            ?? throw new InvalidOperationException(
                "TopologyFingerprint.Compute was not found.");
        return computeMethod.Invoke(null, new object[] { topology }) as string
            ?? throw new InvalidOperationException(
                "TopologyFingerprint.Compute returned an unexpected type.");
    }

    /// <summary>
    /// Thrown by <see cref="ValidateHisNetsFixtures"/> when Param's own
    /// exported studies are not reachable from this machine (no OneDrive,
    /// or not yet synced). Caught separately from every other exception in
    /// <see cref="Run"/> and reported as SKIP rather than a failure: round
    /// four rule 1 requires his nets be the fixtures, but also requires the
    /// harness stay runnable off his OneDrive, and a named skip is the only
    /// shape that satisfies both.
    /// </summary>
    private sealed class HisNetsUnavailableException : Exception
    {
        public HisNetsUnavailableException(string message) : base(message)
        {
        }
    }

    /// <summary>One of Param's eight exported studies, registered as a
    /// permanent fixture (spec 2026-09-06 skin-round-four-his-nets, rule 1).
    /// The five count fields are the diagnosis's own independently-measured
    /// ground truth (2026-09-06 skin-real-net-diagnosis section 1.3), read
    /// a second time here straight off each study's own -form.json rather
    /// than trusted from the report, so a regenerated export that changed
    /// shape would be caught by this table disagreeing with the file, not
    /// by the file disagreeing with itself.</summary>
    private readonly record struct HisNetFixture(
        string Study,
        int Pattern,
        int FormVertices,
        int RawFaces,
        int EquilibriumEdges,
        int Supports,
        int SeedGroups);

    /// <summary>Pattern 1 is hexagonal, per the diagnosis's own finding
    /// (section headline): the three "Hex" studies match ONLY that pattern,
    /// because Param's canvas was set to it when he exported them. Pattern 0
    /// (courses) is every other study, and is also the only pattern those
    /// five studies were ever solved under on his machine.</summary>
    private static readonly HisNetFixture[] HisNetFixtures =
    {
        new("2 sided vault", 0, 441, 400, 800, 42, 2),
        new("2 sided vault Hex", 1, 661, 600, 1200, 63, 3),
        new("3 sided vault", 0, 661, 600, 1200, 63, 3),
        new("3 sided vault Hex", 1, 661, 600, 1200, 63, 3),
        new("4 sided vault", 0, 881, 800, 1600, 84, 4),
        new("4 sided vault Hex", 1, 881, 800, 1600, 84, 4),
        new("5 sided vault", 0, 1101, 1000, 2000, 105, 5),
        new("6 sided vault", 0, 1321, 1200, 2400, 126, 6),
    };

    /// <summary>Where Param's eight studies live. Not configurable: the
    /// point of rule 1 is that HIS nets are the fixtures, at the one place
    /// he exports them to, and a harness that let this be overridden would
    /// let a future run quietly measure something else and call it his
    /// data.</summary>
    private const string HisExportsRoot =
        @"C:\Users\Param\OneDrive - Ananke-eidos\Documents\Kinetic AI\PHD robotics\COMPAS Exports";

    /// <summary>The document's own ground truth for one study, read by a
    /// SECOND, unrelated parse path (a plain JsonDocument walk over the raw
    /// -form.json), never through the loader under test
    /// (<see cref="HisNetExtractResultContractJson"/> plus
    /// ContractJson.Deserialize plus SkinPatterns.ReadNet). Measuring the
    /// loader's output against a ground truth read by the loader itself
    /// would prove nothing; this is the diagnosis's own method (section
    /// 1.3), lifted rather than re-argued.</summary>
    private readonly record struct HisNetGroundTruth(
        int FormVertices, int RawFaces, int EquilibriumEdges, int Supports);

    private static HisNetGroundTruth ReadHisNetGroundTruth(string formJsonPath)
    {
        using FileStream stream = File.OpenRead(formJsonPath);
        using JsonDocument document = JsonDocument.Parse(stream);
        JsonElement root = document.RootElement;
        return new HisNetGroundTruth(
            root.GetProperty("formGraph").GetProperty("vertices")
                .GetArrayLength(),
            root.GetProperty("formGraph").GetProperty("faces")
                .GetArrayLength(),
            root.GetProperty("equilibrium").GetProperty("edges")
                .GetArrayLength(),
            root.GetProperty("mappings").GetProperty("supports")
                .GetArrayLength());
    }

    /// <summary>
    /// The form document's embedded contract, as the exact JSON text
    /// ContractJson.Serialize(ResultDto) produced, recovered by dropping the
    /// two keys FormDocument.JsonFromContract adds around it ("study" leads,
    /// "thrustMesh" trails). Lifted verbatim from the diagnosis (2026-09-06
    /// skin-real-net-diagnosis section 1.2): a JsonDocument walk rather than
    /// the writer's own byte-offset trick, because a READER parsing a file
    /// it did not just write should not assume the same byte positions, only
    /// that the two keys exist and every other key is the contract's own.
    /// </summary>
    private static string HisNetExtractResultContractJson(string formJsonPath)
    {
        byte[] raw = File.ReadAllBytes(formJsonPath);
        using JsonDocument document = JsonDocument.Parse(raw);
        if (document.RootElement.ValueKind != JsonValueKind.Object)
        {
            throw new InvalidDataException(
                $"{formJsonPath}: root is not a JSON object, so this is " +
                "not a form document FormDocument.JsonFromContract wrote.");
        }
        using var buffer = new MemoryStream();
        int kept = 0;
        using (var writer = new Utf8JsonWriter(buffer))
        {
            writer.WriteStartObject();
            foreach (JsonProperty property in document.RootElement.EnumerateObject())
            {
                if (property.NameEquals("study") ||
                    property.NameEquals("thrustMesh"))
                {
                    continue;
                }
                property.WriteTo(writer);
                kept++;
            }
            writer.WriteEndObject();
        }
        if (kept == 0)
        {
            throw new InvalidDataException(
                $"{formJsonPath}: nothing left once 'study' and " +
                "'thrustMesh' are dropped -- this is not a form document, " +
                "or the two added keys have changed name.");
        }
        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    /// <summary>Per-course cell tally read straight off a -skin.json
    /// sidecar, the studio's bench.tessellation/1 shape
    /// (ExportComponent.BuildSkinJson): course id to cell count. An
    /// independent parse, exactly as <see cref="ReadHisNetGroundTruth"/> is
    /// for the counts, so the reproduction pin cannot pass by construction.
    /// </summary>
    private static Dictionary<int, int> ReadSkinSidecarTally(string skinJsonPath)
    {
        using FileStream stream = File.OpenRead(skinJsonPath);
        using JsonDocument document = JsonDocument.Parse(stream);
        var tally = new Dictionary<int, int>();
        foreach (JsonElement cell in
            document.RootElement.GetProperty("cells").EnumerateArray())
        {
            int course = cell.GetProperty("course").GetInt32();
            tally[course] = tally.GetValueOrDefault(course) + 1;
        }
        return tally;
    }

    private static string FormatCourseTally(IReadOnlyDictionary<int, int> tally) =>
        "{" + string.Join(
            ", ",
            tally.OrderBy(entry => entry.Key)
                .Select(entry => $"{entry.Key}:{entry.Value}")) + "}";

    /// <summary>
    /// RULE 1 of spec 2026-09-06 skin-round-four-his-nets: Param's own eight
    /// exported studies, permanently registered. For each: the loader
    /// (<see cref="HisNetExtractResultContractJson"/> into
    /// ContractJson.Deserialize into SkinPatterns.ReadNet, every type
    /// resolved against the built .gha exactly as the rest of this harness
    /// resolves plugin types) is exercised, the resulting net's counts are
    /// checked against the document's own independently-read ground truth,
    /// the registered pattern is solved at his canvas settings, and the
    /// generated cell count and per-course tally are checked, as a
    /// REPRODUCTION PIN, against the -skin.json sidecar his own machine
    /// wrote for that study. If the exports folder (or any one of the
    /// sixteen files this needs) is not reachable, every one of the eight
    /// is SKIPPED with a named reason rather than failed, so the harness
    /// stays runnable on a machine without his OneDrive.
    /// </summary>
    private static void ValidateHisNetsFixtures(Assembly plugin)
    {
        if (!Directory.Exists(HisExportsRoot))
        {
            throw new HisNetsUnavailableException(
                $"COMPAS Exports folder not found at '{HisExportsRoot}' " +
                "(no OneDrive on this machine, or not yet synced).");
        }

        Type patterns = RequireComponentType(plugin, "SkinPatterns");
        Type netType = RequireComponentType(plugin, "SkinNet");
        Type resultType = RequireContractType(plugin, "ResultDto");
        MethodInfo readNet = RequirePublicStatic(patterns, "ReadNet");
        MethodInfo courses = RequirePublicStatic(
            patterns, "Courses",
            netType, typeof(double), typeof(double), typeof(double));
        MethodInfo hexagonal = RequirePublicStatic(
            patterns, "Hexagonal",
            netType, typeof(double), typeof(double), typeof(double));

        const double Size = 0.5;
        const double CourseHeight = 0.5;
        const double MinPiece = 0.20;

        foreach (HisNetFixture fixture in HisNetFixtures)
        {
            string formPath =
                Path.Combine(HisExportsRoot, $"{fixture.Study}-form.json");
            string skinPath =
                Path.Combine(HisExportsRoot, $"{fixture.Study}-skin.json");
            if (!File.Exists(formPath) || !File.Exists(skinPath))
            {
                throw new HisNetsUnavailableException(
                    $"'{fixture.Study}' is missing its -form.json or " +
                    $"-skin.json under '{HisExportsRoot}'.");
            }

            HisNetGroundTruth truth = ReadHisNetGroundTruth(formPath);
            if (truth.FormVertices != fixture.FormVertices ||
                truth.RawFaces != fixture.RawFaces ||
                truth.EquilibriumEdges != fixture.EquilibriumEdges ||
                truth.Supports != fixture.Supports)
            {
                throw new InvalidOperationException(
                    $"'{fixture.Study}': its own -form.json no longer " +
                    $"reads {fixture.FormVertices} form vertices, " +
                    $"{fixture.RawFaces} raw faces, " +
                    $"{fixture.EquilibriumEdges} equilibrium edges and " +
                    $"{fixture.Supports} supports (registered ground " +
                    $"truth); got {truth.FormVertices} vertices, " +
                    $"{truth.RawFaces} faces, {truth.EquilibriumEdges} " +
                    $"edges, {truth.Supports} supports. The export was " +
                    "regenerated with different geometry; re-measure and " +
                    "update the registered fixture.");
            }

            object resultDto = DeserializeContract(
                plugin, resultType,
                HisNetExtractResultContractJson(formPath));
            object? net = readNet.Invoke(null, new object?[] { resultDto });
            if (net is null)
            {
                throw new InvalidOperationException(
                    $"'{fixture.Study}': SkinPatterns.ReadNet returned " +
                    "null on Param's own exported form document, so every " +
                    "claim below would hold vacuously.");
            }

            int rimDropped = Reading<int>(net, "RimDropped");
            int edgesDropped = Reading<int>(net, "EdgesDropped");
            int netVertices = ((IEnumerable)netType
                    .GetProperty("Vertices")!.GetValue(net)!)
                .Cast<double[]>().Count();
            int netFaces = ((IEnumerable)netType
                    .GetProperty("Faces")!.GetValue(net)!)
                .Cast<int[]>().Count();
            int netEdges = ((IEnumerable)netType
                    .GetProperty("Edges")!.GetValue(net)!)
                .Cast<object>().Count();
            int netRim = ((IEnumerable)netType
                    .GetProperty("Rim")!.GetValue(net)!)
                .Cast<int>().Count();
            int netSeedGroups = ((IEnumerable)netType
                    .GetProperty("SeedGroups")!.GetValue(net)!)
                .Cast<int>().Where(seed => seed >= 0).Distinct().Count();

            if (rimDropped != 0 || edgesDropped != 0 ||
                netVertices != fixture.FormVertices ||
                netFaces != fixture.RawFaces * 2 ||
                netEdges != fixture.EquilibriumEdges ||
                netRim != fixture.Supports ||
                netSeedGroups != fixture.SeedGroups)
            {
                throw new InvalidOperationException(
                    $"'{fixture.Study}': ReadNet must give " +
                    $"{fixture.FormVertices} vertices, " +
                    $"{fixture.RawFaces * 2} triangulated faces, " +
                    $"{fixture.EquilibriumEdges} edges, {fixture.Supports} " +
                    $"rim vertices, {fixture.SeedGroups} seed groups and " +
                    "zero rim/edge drops; got " +
                    $"{netVertices} vertices, {netFaces} faces, " +
                    $"{netEdges} edges, {netRim} rim, {netSeedGroups} " +
                    $"seed groups, {rimDropped} rim dropped, " +
                    $"{edgesDropped} edges dropped.");
            }

            object generated = fixture.Pattern == 1
                ? hexagonal.Invoke(
                    null,
                    new object[] { net, Size, CourseHeight, MinPiece })!
                : courses.Invoke(
                    null,
                    new object[] { net, Size, CourseHeight, MinPiece })!;
            IEnumerable cells =
                (IEnumerable)generated.GetType()
                    .GetProperty("Cells")!.GetValue(generated)!;
            var computedTally = new Dictionary<int, int>();
            foreach (object cell in cells)
            {
                int course = Reading<int>(cell, "Course");
                computedTally[course] =
                    computedTally.GetValueOrDefault(course) + 1;
            }
            Dictionary<int, int> sidecarTally = ReadSkinSidecarTally(skinPath);
            // ROUND FIVE (spec 2026-09-06-skin-round-five-honeycomb-and-
            // convergence.md, rule 1.2): the honeycomb row fix deliberately
            // diverges the three Hex studies from Param's own sidecar,
            // which his machine wrote under the OLD, overlapping-row
            // construction -- this is round five's entire point ("the
            // kept-cell set must GROW... that is the proof the visible
            // geometry changed"), not a regression to paper over. The five
            // courses-pattern studies are untouched by this fix and keep
            // the exact sidecar reproduction pin unchanged; the three Hex
            // studies are checked against HexReproductionPins instead, a
            // tally frozen at this wave's own measurement, with the old
            // (now-stale) sidecar tally still read and reported alongside
            // it so the divergence stays on the record rather than silent.
            bool isHex = fixture.Pattern == 1;
            bool hasOwnPin =
                isHex || HexReproductionPins.ContainsKey(fixture.Study);
            Dictionary<int, int>? ownPin = hasOwnPin
                ? HexReproductionPins[fixture.Study]
                : null;
            Dictionary<int, int> expectedTally = ownPin ?? sidecarTally;
            bool tallyMatches =
                computedTally.Count == expectedTally.Count &&
                computedTally.All(entry =>
                    expectedTally.TryGetValue(entry.Key, out int expected) &&
                    expected == entry.Value);
            if (!tallyMatches)
            {
                throw new InvalidOperationException(
                    $"'{fixture.Study}' (pattern {fixture.Pattern}): the " +
                    "reproduction pin failed. This harness's own " +
                    $"per-course cell tally is {FormatCourseTally(computedTally)} " +
                    $"({computedTally.Values.Sum()} cells); " +
                    (hasOwnPin
                        ? "the deliberate-divergence reproduction pin reads "
                        : "Param's own -skin.json sidecar reads ") +
                    $"{FormatCourseTally(expectedTally)} " +
                    $"({expectedTally.Values.Sum()} cells). His own " +
                    "machine's reproduction is the instrument that was " +
                    "missing all week; a mismatch here means a change has " +
                    "diverged from " +
                    (hasOwnPin
                        ? "that pin's own measurement."
                        : "his reality.")
                );
            }
            if (isHex)
            {
                // NAMED, NOT HIDDEN: his own sidecar (the OLD, overlapping
                // -row engine's output) is expected to disagree now, and
                // by how much is exactly rule 1.2's own proof that the
                // visible geometry changed.
                int oldCount = sidecarTally.Values.Sum();
                int newCount = computedTally.Values.Sum();
                if (newCount <= oldCount)
                {
                    throw new InvalidOperationException(
                        $"'{fixture.Study}': round five's own acceptance " +
                        "bar (rule 1.2) is that the KEPT-cell set GROWS " +
                        $"against his old sidecar's {oldCount} cells; this " +
                        $"build reads {newCount}, which does not grow.");
                }
            }
        }
    }

