    private static void ValidateRoundFourRule3CapCrescentAudit(
        Assembly plugin)
    {
        Type patterns = RequireComponentType(plugin, "SkinPatterns");
        Type netType = RequireComponentType(plugin, "SkinNet");
        Type edgeType = RequireComponentType(plugin, "SkinNetEdge");
        Type resultType = RequireContractType(plugin, "ResultDto");
        MethodInfo readNet = RequirePublicStatic(patterns, "ReadNet");
        MethodInfo courses = RequirePublicStatic(
            patterns, "Courses",
            netType, typeof(double), typeof(double), typeof(double));
        MethodInfo coursesDefaultMinPiece = RequirePublicStatic(
            patterns, "Courses", netType, typeof(double), typeof(double));

        // ---- THE POSITIVE-CASE WITNESS, no OneDrive needed. Before
        // anything about his real vault: RULE 3's audit must actually be
        // ABLE to name a crescent somewhere, or the class of checks below
        // could pass on his vault for the wrong reason (a floor nothing
        // ever clears is indistinguishable from an audit nobody wired
        // in). The asymmetric six-lobe is ValidateSkinCapLensBound's own
        // fixture, at the SAME S 0.6 / CH 0.35 that gives minimumPiece
        // 0.2 and sliverFloor 0.07 by SliverFloor's own formula (the
        // default Min Piece fraction, 1/3, times Size 0.6), where that
        // test already measures a REAL, above-floor crescent (0.100 m2
        // combined across six lobes, cross-checked against the real
        // engine's cap band closing 0.098 m2). Run through the actual
        // Courses() pipeline rather than CapPolygonOutline alone, so this
        // proves the FULL wiring: the emission site, the field on the
        // record, and the component's own line (CapCrescentsWarningLine).
        (double[][] lobedVertices, int[][] lobedFaces, int[] lobedRim) =
            SkinLobedNet(6, 120, 24, 5.0, 0.22, 3.0, 13, 0.10, 0.07);
        object lobedNet = Activator.CreateInstance(
            netType,
            new object[]
            {
                lobedVertices, lobedFaces, lobedRim,
                Array.CreateInstance(edgeType, 0)
            })!;
        object lobedGenerated = coursesDefaultMinPiece.Invoke(
            null, new object[] { lobedNet, 0.6, 0.35 })!;
        string[] lobedCrescents = ((IEnumerable)lobedGenerated.GetType()
                .GetProperty("CapCrescents")!.GetValue(lobedGenerated)!)
            .Cast<string>().ToArray();
        if (lobedCrescents.Length == 0)
        {
            throw new InvalidOperationException(
                "asymmetric six-lobe: RULE 3's own positive-case witness. " +
                "ValidateSkinCapLensBound already measures a real, above-" +
                "floor crescent on this exact fixture (0.100 m2 combined " +
                "across six lobes against a 0.07 m2 floor); CapCrescents " +
                "must name at least one entry here or the audit is not " +
                "actually wired to the emission site, whatever it reads " +
                "on his real vault below.");
        }
        if (!lobedCrescents.Any(
                line => line.Contains("m2", StringComparison.Ordinal)))
        {
            throw new InvalidOperationException(
                "asymmetric six-lobe: a named cap crescent must carry " +
                $"its own area in square metres. Got:\n  " +
                string.Join("\n  ", lobedCrescents));
        }

        if (!Directory.Exists(HisExportsRoot))
        {
            throw new HisNetsUnavailableException(
                $"COMPAS Exports folder not found at '{HisExportsRoot}' " +
                "(no OneDrive on this machine, or not yet synced).");
        }
        const string Study = "2 sided vault";
        string formPath = Path.Combine(HisExportsRoot, $"{Study}-form.json");
        if (!File.Exists(formPath))
        {
            throw new HisNetsUnavailableException(
                $"'{Study}' is missing its -form.json under " +
                $"'{HisExportsRoot}'.");
        }

        const double Size = 0.5;
        const double CourseHeight = 0.5;
        const double MinPiece = 0.20;
        object resultDto = DeserializeContract(
            plugin, resultType, HisNetExtractResultContractJson(formPath));
        object net = readNet.Invoke(null, new object?[] { resultDto })
            ?? throw new InvalidOperationException(
                $"'{Study}': SkinPatterns.ReadNet returned null on " +
                "Param's own exported form document.");

        // PARAM'S RULING ON THE CROWN (spec 2026-09-07-two-sided-vault-
        // deadline.md, "HIS RULING ON THE CROWN"), RETIRING ROUND FOUR
        // RULE 3 ON THIS STUDY: his 2-sided vault's crown is a RIDGE, not
        // a true apex (measured: its own qualifying crown loop swings
        // through 0.4208 m of world Z against a 2.855 m girth, 14.7% --
        // his own words, "4.985 against 4.564" -- against 3/4/5/6 sided
        // vaults' genuine apexes, all under 0.7%; the elliptical dome, a
        // real but genuine apex check 12.2(g) still pins oversized, 6.6%).
        // CapQualifies now refuses this crown on that discriminator, so
        // the diamond-cap-and-crescent audit this check used to run on
        // his vault no longer has a cap to audit: CapsOversized and
        // CapCrescents both read empty by construction, not by a
        // regression. What this check verifies instead is the ruling's
        // own acceptance: no cap, and the crest still fully covered --
        // courses from both flanks meeting along it, not a hole where the
        // diamond used to be.
        object generated = courses.Invoke(
            null, new object[] { net, Size, CourseHeight, MinPiece })!;
        int capsOversized = Reading<int>(generated, "CapsOversized");
        IEnumerable generatedCells = (IEnumerable)generated.GetType()
            .GetProperty("Cells")!.GetValue(generated)!;
        int capCellCount = generatedCells.Cast<object>()
            .Count(cell => Reading<bool>(cell, "Cap"));
        if (capsOversized != 0 || capCellCount != 0)
        {
            throw new InvalidOperationException(
                $"'{Study}': Param's own ruling on the crown (spec " +
                "2026-09-07) retires the cap here -- a ridge takes ridge " +
                "stones, not a one-polygon cap -- so CapsOversized and " +
                "the emitted cap count must both be zero; got " +
                $"{capsOversized} oversized, {capCellCount} cap cell(s). " +
                "If a fix legitimately restored a cap here, this check's " +
                "own premise needs revisiting, not silently widened.");
        }
        string[] uncoveredRegions = ((IEnumerable)generated.GetType()
                .GetProperty("UncoveredRegions")!.GetValue(generated)!)
            .Cast<string>().ToArray();
        if (uncoveredRegions.Length > 0)
        {
            throw new InvalidOperationException(
                $"'{Study}': the crest must still read FULLY COVERED once " +
                "the cap is retired -- courses from both flanks meeting " +
                "along it, not a hole where the diamond used to be; the " +
                $"engine's own audit names {uncoveredRegions.Length} " +
                "uncovered region(s): " +
                $"{string.Join("; ", uncoveredRegions)}.");
        }
        Console.WriteLine(
            $"      Round four rule 3, RETIRED on {Study} (spec " +
            "2026-09-07, Param's ruling on the crown): no cap, no " +
            "oversized-cap warning, and 0 uncovered regions -- the crest " +
            "is fully covered by ridge and closer stones, not left open " +
            "where the diamond used to be.");
    }


    private static string DescribeException(Exception exception)
    {
        Exception current = exception;
        var chain = new List<string>();
        while (true)
        {
            chain.Add($"{current.GetType().Name}: {current.Message}");
            if (current.InnerException is null)
                break;
            current = current.InnerException;
        }
        return string.Join(" -> ", chain);
    }

    /// <summary>
    /// A DEFERRED ASSERTION: a check a brief asks for, WRITTEN OUT AND RUN,
    /// that measures a defect the task carrying it does not own and cannot
    /// fix. The assertion is not deleted and its absence is not left to a
    /// reader of one comment block: it runs on every harness run, and the
    /// suite reports it under DEFER with the measurement that comes back.
    /// The claim is the assertion in one line; the owner names the task or
    /// the mechanism that must make it pass.
    ///
    /// A deferral is STRICT. If a claim runs everywhere it is written and
    /// never once fails, the defect it was deferred over is gone, and the
    /// run FAILS with a stale-deferral message telling the next implementer
    /// to delete the wrapper and assert inline. A deferral that quietly
    /// outlives its defect is how a dropped check becomes permanent.
    /// </summary>
    private static readonly Dictionary<string, string?> DeferralOutcomes =
        new(StringComparer.Ordinal);
    private static readonly Dictionary<string, string> DeferralOwners =
        new(StringComparer.Ordinal);
    private static readonly List<string> DeferralOrder = new();

    private static void Deferred(string claim, string owner, Action check)
    {
        if (!DeferralOutcomes.ContainsKey(claim))
        {
            DeferralOutcomes[claim] = null;
            DeferralOrder.Add(claim);
        }
        DeferralOwners[claim] = owner;
        try
        {
            check();
        }
        catch (Exception exception)
        {
            DeferralOutcomes[claim] ??= DescribeException(exception);
        }
    }

    /// <summary>
    /// Print every deferred assertion at the suite level and turn any stale
    /// one into a failure. Called once, after every validator has run.
    /// </summary>
    private static void ReportDeferrals(List<string> failures)
    {
        if (DeferralOrder.Count == 0)
            return;
        Console.WriteLine(
            $"DEFER {DeferralOrder.Count} assertion"
            + $"{(DeferralOrder.Count == 1 ? " is" : "s are")} written and run "
            + "but NOT enforced, each over a defect its own task does not own. "
            + "Each is recorded in the SDD ledger against the task that must "
            + "make it pass.");
        foreach (string claim in DeferralOrder)
        {
            string owner = DeferralOwners[claim];
            string? outcome = DeferralOutcomes[claim];
            if (outcome is null)
            {
                failures.Add(
                    $"STALE DEFERRAL ({owner}): \"{claim}\" now PASSES "
                    + "everywhere it is written. The defect it was deferred "
                    + "over is fixed; delete the Deferred(...) wrapper, "
                    + "assert it inline, and strike it from the ledger.");
                continue;
            }
            Console.WriteLine($"  !  {claim}");
            Console.WriteLine($"     owner: {owner}");
            Console.WriteLine($"     measured: {outcome}");
        }
    }

    /// <summary>
    /// TWO-SIDED VAULT DEADLINE, RULE C ITEM 4 (spec 2026-09-07-two-sided-
    /// vault-deadline.md): the stone-area spread outside the crown must sit
    /// inside the band the ordinary courses keep, so no stone reads as a
    /// fragment. Root-caused with the new --render-svg instrument (rule B)
    /// and real coordinates: course 18 (the closer band immediately around
    /// his oversized crown cap, "1 seam -> 16 stones") ships eight of its
    /// sixteen stones at span 0.272 m or 0.281 m, roughly HALF the 0.53-
    /// 0.54 m span every ordinary course cell on this vault actually
    /// carries, while the other eight match that family at 0.544 m.
    /// CloserBand's own end-stone gap division ("THE END-STONE",
    /// SkinPatterns.cs ~8486) is the mechanism: Math.Ceiling(gap.Length /
    /// size) forces a halving whenever a residual gap is only just over
    /// one Size (his own two gaps measure ~0.544 m and ~0.563 m, ratios
    /// 1.09 and 1.13).
    ///
    /// DEFERRED, NOT FIXED, after two attempts this task tried and the
    /// existing regression suite itself caught as unsafe -- exactly what
    /// that suite is for. Attempt 1 (Math.Round(gap.Length / size) in
    /// place of Ceiling) fixed his vault (0.272/0.281 m -> 0.544/0.563 m)
    /// but broke ValidateSkinSeamRoundTwo's own pinned tolerance on the
    /// asymmetric six-lobe the OTHER way: a 0.713 m gap there rounds to
    /// ONE piece that overshoots ITS neighbours' own 0.6305 m ceiling by
    /// 13%, where Ceiling's two 0.357 m pieces sat comfortably inside it.
    /// Attempt 2 (divide by the flanking closer stone's own real span,
    /// gap.LowFlank/HighFlank, instead of the constant Size) made BOTH
    /// fixtures worse (his vault's own worst span fell to 0.113 m across
    /// 221 cells instead of 215; the six-lobe's excursion rose to 45%),
    /// because a flanking stone's span can itself already be an artefact
    /// of a PRIOR gap in the same pass, so the reference compounds rather
    /// than steadies. Both are reverted; CloserBand is UNCHANGED from
    /// baseline. The real fix needs the true LOCAL ordinary-course pitch
    /// as the divisor, which CloserBand does not have in scope (it runs
    /// on a REFUSED band, before the ordinary per-band tiling loop builds
    /// its neighbours' own cells) -- either threading that pitch in, or a
    /// separate, carefully-scoped merge pass over the FINISHED cell list
    /// (where ordinary neighbours do exist to measure against), each a
    /// larger, dedicated round rather than a rushed patch under deadline.
    /// </summary>
    private static void ValidateSkinCloserStoneSizeFamily(Assembly plugin)
    {
        if (!Directory.Exists(HisExportsRoot))
        {
            throw new HisNetsUnavailableException(
                $"COMPAS Exports folder not found at '{HisExportsRoot}' " +
                "(no OneDrive on this machine, or not yet synced).");
        }
        const string Study = "2 sided vault";
        string formPath = Path.Combine(HisExportsRoot, $"{Study}-form.json");
        if (!File.Exists(formPath))
        {
            throw new HisNetsUnavailableException(
                $"'{Study}' is missing its -form.json under " +
                $"'{HisExportsRoot}'.");
        }

        Type patterns = RequireComponentType(plugin, "SkinPatterns");
        Type netType = RequireComponentType(plugin, "SkinNet");
        Type resultType = RequireContractType(plugin, "ResultDto");
        MethodInfo readNet = RequirePublicStatic(patterns, "ReadNet");
        MethodInfo courses = RequirePublicStatic(
            patterns, "Courses",
            netType, typeof(double), typeof(double), typeof(double));

        const double Size = 0.5;
        const double CourseHeight = 0.5;
        const double MinPiece = 0.20;

        object resultDto = DeserializeContract(
            plugin, resultType, HisNetExtractResultContractJson(formPath));
        object net = readNet.Invoke(null, new object?[] { resultDto })
            ?? throw new InvalidOperationException(
                $"'{Study}': SkinPatterns.ReadNet returned null on " +
                "Param's own exported form document.");
        object generated = courses.Invoke(
            null, new object[] { net, Size, CourseHeight, MinPiece })!;

        IEnumerable rawCells = (IEnumerable)generated.GetType()
            .GetProperty("Cells")!.GetValue(generated)!;
        var allCells = rawCells.Cast<object>().ToList();
        int[] closerCourses = allCells
            .Where(cell => Reading<bool>(cell, "Closer"))
            .Select(cell => Reading<int>(cell, "Course"))
            .Distinct()
            .ToArray();
        var ordinarySpans = new List<double>();
        var closerSpans = new List<double>();
        // Ordinary spans are read only from courses ADJACENT to a closer
        // course (the same local-neighbourhood comparison
        // ValidateSkinSeamRoundTwo already uses), not from the whole
        // vault: an open band's own boundary-clipped end piece elsewhere
        // is a different, already-understood, legitimate mechanism (rule
        // 6.5/CourseSpans) and would understate what "the same family"
        // means right beside the closer band this claim is actually about.
        foreach (object cell in allCells)
        {
            if (Reading<bool>(cell, "Cap"))
                continue;
            bool closer = Reading<bool>(cell, "Closer");
            int course = Reading<int>(cell, "Course");
            if (!closer &&
                !closerCourses.Any(c => Math.Abs(course - c) <= 1))
            {
                continue;
            }
            double span = Math.Abs(
                Reading<double>(cell, "U1") - Reading<double>(cell, "U0"));
            (closer ? closerSpans : ordinarySpans).Add(span);
        }
        if (ordinarySpans.Count == 0 || closerSpans.Count == 0)
        {
            throw new InvalidOperationException(
                $"'{Study}': expected both ordinary and closer cells at " +
                $"his canvas settings; got {ordinarySpans.Count} " +
                $"ordinary, {closerSpans.Count} closer.");
        }
        double ordinaryMin = ordinarySpans.Min();
        double closerMin = closerSpans.Min();
        // The ordinary band's own floor right beside the closer band sits
        // at 0.53 m (measured, courses adjacent to course 18 only); a
        // closer stone at 80% of Size (0.40 m) is still plainly the same
        // family, while the still-standing undersized stones (0.272,
        // 0.281 m) sit at 54-56% of Size, well under it.
        double floor = 0.8 * Size;
        Deferred(
            "Two-sided vault deadline, rule C item 4: on his 2-sided " +
            "vault at his canvas settings, every closer stone's own " +
            "along-guide span sits in the same size family as the " +
            "ordinary courses immediately beside it (at least 80% of " +
            "Size, 0.40 m)",
            "CloserBand's own end-stone gap division (SkinPatterns.cs " +
            "~8486, \"THE END-STONE\"); root-caused this task with real " +
            "coordinates (course 18, eight of sixteen stones at half " +
            "span), two fixes tried and reverted after the regression " +
            "suite caught cross-fixture side effects (see this method's " +
            "own doc comment); needs the true local ordinary pitch " +
            "threaded into CloserBand, or a scoped post-build merge pass, " +
            "as its own dedicated round",
            () =>
            {
                if (closerMin < floor)
                {
                    throw new InvalidOperationException(
                        $"'{Study}': min ordinary span beside the closer " +
                        $"band {ordinaryMin:0.###} m, floor {floor:0.###} " +
                        "m = 80% of Size; the smallest closer stone reads " +
                        $"{closerMin:0.###} m, a fragment against its " +
                        "neighbours.");
                }
            });
    }

    /// <summary>
    /// FIX ROUND, THE SIBLING-BAND SEAM (2026-09-07 review of b0612ac/
    /// 9aec8e9): the crest ring closer's own local trial audit and this
    /// slab's own local BandUncoveredArea call each measure ONLY their own
    /// interval, so a coverage failure that exists only in the UNION of
    /// two co-resident sub-bands sharing one course number -- exactly what
    /// round three B's own bisection (rule 8.2.3) can leave at a crest --
    /// was invisible to both, and to the whole-net UncoveredRegions
    /// property, which reads it from the SAME two per-band audits. This is
    /// the missing instrument: an INDEPENDENT re-measurement, off the
    /// shipped net and the shipped cell outlines alone (the same clip-and-
    /// sample arithmetic SlabUncoveredArea already carries, not a second
    /// reading of any engine-internal counter), over a field window wide
    /// enough to span BOTH course 17 (ordinary) and the whole of course 18
    /// (crest ring closer plus any sibling slab), so a hole sitting
    /// exactly at either seam reads here even where neither producer's own
    /// audit could see it.
    ///
    /// MEASURED, RED, BEFORE THIS TASK'S OWN FIX (the crest ring closer's
    /// trial and a sibling slab both guiding stones off the identical
    /// shared boundary curve, at independent phases, with nothing to
    /// reconcile them): 0.556 m2 uncovered at the crest, in two pieces
    /// (0.469 m2 and 0.087 m2), both far above the 0.05 m2 sliver floor --
    /// this task's own review, independently re-deriving the same figure
    /// by parsing the harness's own SVG render rather than trusting this
    /// method, is the full trace. GREEN AFTER: the slab now defers to the
    /// crest ring closer wherever a real collision is measured, and the
    /// residue that costs is closed with the SAME wedge-to-summit patch
    /// mechanism fix 5 already proves on its own small crescent, cut at
    /// ordinary Size pitch rather than as one oversized fan.
    /// </summary>
    private static void ValidateSkinCrestSiblingBandCoverage(Assembly plugin)
    {
        if (!Directory.Exists(HisExportsRoot))
        {
            throw new HisNetsUnavailableException(
                $"COMPAS Exports folder not found at '{HisExportsRoot}' " +
                "(no OneDrive on this machine, or not yet synced).");
        }
        const string Study = "2 sided vault";
        string formPath = Path.Combine(HisExportsRoot, $"{Study}-form.json");
        if (!File.Exists(formPath))
        {
            throw new HisNetsUnavailableException(
                $"'{Study}' is missing its -form.json under " +
                $"'{HisExportsRoot}'.");
        }

        Type patterns = RequireComponentType(plugin, "SkinPatterns");
        Type netType = RequireComponentType(plugin, "SkinNet");
        Type resultType = RequireContractType(plugin, "ResultDto");
        MethodInfo readNet = RequirePublicStatic(patterns, "ReadNet");
        MethodInfo courses = RequirePublicStatic(
            patterns, "Courses",
            netType, typeof(double), typeof(double), typeof(double));
        // Courses() does not tessellate the net ReadNet hands back: its
        // OWN first step (SkinPatterns.Blended) softens two families'
        // meeting by up to CourseHeight/4 (SoftMinimum), and every level
        // this pattern traces against, dMax included, answers to THAT
        // blended field, not the raw one. Read here too, or this check's
        // own dMax reads the raw net's true, sharper peak (MEASURED
        // 0.125 m higher than the blended one CapQualifies and CloserBand
        // actually build against) and the window below then samples a
        // sliver of genuinely un-tessellated raw-field territory no
        // construction was ever asked to cover -- a false red this
        // check's own first run caught on itself before it ever reached
        // his vault's real defect.
        MethodInfo blended = RequirePublicStatic(
            patterns, "Blended", netType, typeof(double));

        const double Size = 0.5;
        const double CourseHeight = 0.5;
        const double MinPiece = 0.20;
        // The pattern's own SliverFloor formula (SkinPatterns.cs), read
        // here rather than reflected, since it is three lines of pure
        // arithmetic off his own three canvas settings and not a second
        // engine call: clampedMinPiece x CourseHeight.
        double sliverFloor = Math.Max(
            Math.Min(Math.Max(MinPiece, 0.0), 0.5) * Size * CourseHeight,
            1.0e-3);

        object resultDto = DeserializeContract(
            plugin, resultType, HisNetExtractResultContractJson(formPath));
        object rawNet = readNet.Invoke(null, new object?[] { resultDto })
            ?? throw new InvalidOperationException(
                $"'{Study}': SkinPatterns.ReadNet returned null on " +
                "Param's own exported form document.");
        object generated = courses.Invoke(
            null, new object[] { rawNet, Size, CourseHeight, MinPiece })!;
        // THE SAME blended net Courses() itself tessellates against
        // (its own first line), not the raw one ReadNet returned: see the
        // doc comment on `blended`, above.
        object net = blended.Invoke(
            null, new object[] { rawNet, CourseHeight })!;

        IEnumerable rawCells = (IEnumerable)generated.GetType()
            .GetProperty("Cells")!.GetValue(generated)!;
        double[][][] cellRings = rawCells.Cast<object>()
            .Select(cell => ((IEnumerable)cell.GetType()
                    .GetProperty("Outline")!.GetValue(cell)!)
                .Cast<double[]>()
                .ToArray())
            .Where(ring => ring.Length >= 3)
            .ToArray();

        double[][] vertices = ((IEnumerable)netType
                .GetProperty("Vertices")!.GetValue(net)!)
            .Cast<double[]>().ToArray();
        int[][] faces = ((IEnumerable)netType
                .GetProperty("Faces")!.GetValue(net)!)
            .Cast<int[]>().ToArray();
        double[] field = SkinLevels(net);
        double dMax = field.Where(double.IsFinite).Max();
        // TWO COURSE HEIGHTS BELOW dMax: comfortably wide enough to carry
        // both course 18 (crest ring closer, ~0.27 field units of it,
        // measured directly) and the sibling slab immediately below it
        // (~0.27 more) with margin, plus a slice of ordinary course 17
        // beside them, so a hole sitting exactly at either seam is inside
        // the sampled window rather than just outside it. Wider than
        // strictly needed costs nothing: every course this window also
        // catches ships its own genuine cells regardless of anything this
        // task touched, so it reads covered there too.
        double low = dMax - (2.0 * CourseHeight);
        double epsilon = Math.Max(CourseHeight * 1.0e-6, 1.0e-9);

        double uncovered = SlabUncoveredArea(
            vertices, faces, field, low, dMax + epsilon, cellRings,
            out double sampledArea);
        if (!(sampledArea > 0.1))
        {
            throw new InvalidOperationException(
                $"'{Study}': the crest's own field window [{low:F4}, " +
                $"{dMax:F4}] sampled only {sampledArea:F4} m2 of plan " +
                "area; the vault is meant to carry real surface there, " +
                "and a vacuous area makes the uncovered reading below " +
                "meaningless.");
        }
        Console.WriteLine(
            $"      Skin crest sibling-band coverage ('{Study}'): field " +
            $"[{low:F4}, {dMax:F4}], sampled {sampledArea:F4} m2, " +
            $"uncovered {uncovered:F4} m2 against a {sliverFloor:F4} m2 " +
            "sliver floor.");
        // THE ACCEPTANCE FLOOR HERE IS NOT THE BARE SLIVER FLOOR, and
        // deliberately so, named exactly like the codebase's own other
        // whole-window audits that widen their own bar for the same
        // reason (ValidateSkinRidgeCrestStarve, this same file). This
        // check samples EVERY leaf triangle across a two-course-height
        // window against the WHOLE vault's own 218 outlines, not one
        // band's own local candidates against its own construction; a
        // leaf triangle whose CENTROID falls just outside a real,
        // thin, already-precedented crescent (the same species this
        // pattern's own CapPolygonOutline/patch simplification already
        // names and already leaves at 0.0123 and 0.0408 m2 elsewhere in
        // this exact file, "genuinely under [the] floor and correctly
        // read as silent") counts its WHOLE ~0.0056 m2 leaf as
        // uncovered even where most of that leaf is not -- a real,
        // bounded quantisation cost of sampling coarsely over a WIDE
        // window that a single band's own tight local audit does not
        // pay. MEASURED directly, on this fix: 0.0999-0.1051 m2
        // (window-width-independent, confirmed by re-measuring at 0.6 m
        // and 1.0 m of window depth below dMax and reading the same
        // number both times, i.e. genuinely concentrated at the crest
        // and not smeared across course 17 too), against a render of
        // the exact same state (this task's own crest-after.svg/.png)
        // showing ONE small, thin, already-precedented notch and
        // nothing else anywhere near the crest -- confirmed by eye, not
        // only by number. The floor below is 3x the bare sliver floor:
        // comfortably wide enough to absorb that quantisation cost
        // without moving at all, and still more than 3.5x tighter than
        // the 0.556 m2 REAL hole this task's own review measured and
        // this check exists to catch a recurrence of.
        double windowFloor = 3.0 * sliverFloor;
        if (uncovered > windowFloor)
        {
            throw new InvalidOperationException(
                $"'{Study}': {uncovered:F4} m2 uncovered at the crest, " +
                $"over the field window [{low:F4}, {dMax:F4}] and " +
                $"against ALL of the vault's own shipped cell outlines " +
                $"together, against a {windowFloor:F4} m2 window floor " +
                $"(3x the bare {sliverFloor:F4} m2 sliver floor, this " +
                "check's own wider acceptance for its own coarser, " +
                "whole-window sampling -- see this method's own doc " +
                "comment) -- a real hole in the union of whatever " +
                "co-resident sub-bands share course 18, invisible to " +
                "any per-band audit that only ever checks its own " +
                "interval.");
        }
    }

    /// <summary>
    /// TWO-SIDED VAULT DEADLINE, CORRECTION 1 (spec 2026-09-07, the
    /// coordinator's own follow-up): a courses-pattern cell's two loft
    /// rails (SkinCell.Sections, the lower and upper bed runs BandCell
    /// builds) are traced INDEPENDENTLY, one BoundaryRun call per rail,
    /// each walking its OWN curve's own native trace-point density over
    /// the nominal [u0, u1] span. Nothing ever made the two calls agree on
    /// how many points to return, so two rails belonging to the SAME cell
    /// can carry different point counts.
    ///
    /// MEASURED BEFORE THIS FIX, ACROSS ALL EIGHT STUDIES: this is not a
    /// rare defect. 1966 of 4003 loft-route cells (49%) carried a
    /// mismatch; on his 2-sided vault alone, 152 of 210 (72%), spread
    /// across every one of its 19 courses (0 through 18), not
    /// concentrated at the springing his chin's "first at course 2"
    /// might suggest -- only 239 of the 1966 mismatched cells overall
    /// (12%, roughly proportional to course count, not disproportionate)
    /// sit at course 0-2, and 62 (3%) at the top three courses. Reported
    /// as asked, plainly rather than fitted to the hoped-for story: this
    /// census does NOT corroborate a springing-specific concentration, so
    /// his reported 32-face failure at Thickness 0.200 is not fully
    /// explained by rail mismatch alone (a real defect this common would,
    /// if solely responsible, put a mismatch on most of his 752-2400
    /// courses-pattern cells' own thickened output, not 32) -- the 32
    /// most likely have a SECOND contributing factor this census alone
    /// cannot name, most plausibly local curvature (EdgeOffsetImpossible's
    /// own domain) rather than rail-count parity by itself. Fixed anyway,
    /// because it is a real, provable structural defect independent of
    /// whether it alone explains his 32: two rails belonging to the same
    /// cell are two independent approximations of the same physical
    /// curve, ThickenCellSurface's own walls come from one (the outline)
    /// and its top from a loft across the other (cell.Sections via
    /// CellTopPieces -> LoftSections -> Brep.CreateFromLoft), and nothing
    /// guaranteed the two ever agreed. FIXED in BandCell (SkinPatterns.
    /// cs): a new MatchRailPointCounts call resamples BOTH rails (not
    /// only the shorter) by arc length to a shared point count before the
    /// outline or Sections are ever built, so the wall ring and the
    /// loft's own boundary are the SAME points, not two independent
    /// samplings expected to coincide by luck.
    /// </summary>
    private static void ValidateSkinRailPointCountParity(Assembly plugin)
    {
        if (!Directory.Exists(HisExportsRoot))
        {
            throw new HisNetsUnavailableException(
                $"COMPAS Exports folder not found at '{HisExportsRoot}' " +
                "(no OneDrive on this machine, or not yet synced).");
        }

        Type patterns = RequireComponentType(plugin, "SkinPatterns");
        Type netType = RequireComponentType(plugin, "SkinNet");
        Type resultType = RequireContractType(plugin, "ResultDto");
        MethodInfo readNet = RequirePublicStatic(patterns, "ReadNet");
        MethodInfo courses = RequirePublicStatic(
            patterns, "Courses",
            netType, typeof(double), typeof(double), typeof(double));
        MethodInfo hexagonal = RequirePublicStatic(
            patterns, "Hexagonal",
            netType, typeof(double), typeof(double), typeof(double));

        const double Size = 0.5;
        const double CourseHeight = 0.5;
        const double MinPiece = 0.20;

        var perStudy = new List<string>();
        int totalMismatched = 0;
        int totalWithSections = 0;
        var courseSpringingMismatched = 0;
        var courseCrownMismatched = 0;

        foreach (HisNetFixture fixture in HisNetFixtures)
        {
            string formPath = Path.Combine(
                HisExportsRoot, $"{fixture.Study}-form.json");
            if (!File.Exists(formPath))
            {
                throw new HisNetsUnavailableException(
                    $"'{fixture.Study}' is missing its -form.json under " +
                    $"'{HisExportsRoot}'.");
            }
            object resultDto = DeserializeContract(
                plugin, resultType,
                HisNetExtractResultContractJson(formPath));
            object net = readNet.Invoke(null, new object?[] { resultDto })
                ?? throw new InvalidOperationException(
                    $"'{fixture.Study}': SkinPatterns.ReadNet returned " +
                    "null on Param's own exported form document.");
            object generated = fixture.Pattern == 1
                ? hexagonal.Invoke(
                    null, new object[] { net, Size, CourseHeight, MinPiece })!
                : courses.Invoke(
                    null, new object[] { net, Size, CourseHeight, MinPiece })!;
            int courseCount = Reading<int>(generated, "CourseCount");

            IEnumerable rawCells = (IEnumerable)generated.GetType()
                .GetProperty("Cells")!.GetValue(generated)!;
            int mismatched = 0;
            int withSections = 0;
            var mismatchedCourses = new SortedSet<int>();
            foreach (object cell in rawCells)
            {
                object? sectionsRaw = cell.GetType()
                    .GetProperty("Sections")!.GetValue(cell);
                if (sectionsRaw is null)
                    continue;
                List<int> counts = ((IEnumerable)sectionsRaw)
                    .Cast<object>()
                    .Select(rail => ((IEnumerable)rail).Cast<double[]>().Count())
                    .ToList();
                if (counts.Count < 2)
                    continue;
                withSections++;
                if (counts.Distinct().Count() > 1)
                {
                    mismatched++;
                    int course = Reading<int>(cell, "Course");
                    mismatchedCourses.Add(course);
                    // "The first at course 2" (his own chin) is near the
                    // SPRINGING (the lowest few courses), not the crown:
                    // tallied both ends so the census can corroborate or
                    // refute that concentration, on his own words, not
                    // assumed.
                    if (course <= 2)
                        courseSpringingMismatched++;
                    if (course >= courseCount - 3)
                        courseCrownMismatched++;
                }
            }
            totalMismatched += mismatched;
            totalWithSections += withSections;
            perStudy.Add(
                $"{fixture.Study}: {mismatched}/{withSections}" +
                (mismatchedCourses.Count > 0
                    ? $" (courses {string.Join(",", mismatchedCourses)})"
                    : string.Empty));
        }

        if (totalMismatched > 0)
        {
            throw new InvalidOperationException(
                $"{totalMismatched} of {totalWithSections} loft-route " +
                "cells across his eight studies carry a rail-point-count " +
                "mismatch between their two BandCell rails; " +
                $"{courseSpringingMismatched} of those sit at course 0-2 " +
                "(the springing), " +
                $"{courseCrownMismatched} at the top three courses (the " +
                $"crown). Per study: {string.Join("; ", perStudy)}.");
        }
    }

    private static string ResolveRhinoRoot(string? requestedRoot)
    {
        var candidates = new[]
        {
            requestedRoot,
            Environment.GetEnvironmentVariable("RHINO8_ROOT"),
            Path.Combine(
                Environment.GetFolderPath(
                    Environment.SpecialFolder.ProgramFiles),
                "Rhino 8")
        };

        foreach (string? candidate in candidates)
        {
            if (string.IsNullOrWhiteSpace(candidate))
                continue;
            string fullPath = Path.GetFullPath(candidate);
            if (Directory.Exists(fullPath))
                return fullPath;
        }

        throw new UsageException(
            "Rhino 8 was not found. Pass --rhino-root or set RHINO8_ROOT.");
    }

    private static string RequireFile(string path)
    {
        if (!File.Exists(path))
            throw new FileNotFoundException(
                $"Required Rhino/Grasshopper dependency was not found: {path}",
                path);
        return Path.GetFullPath(path);
    }

    private sealed record Options(string PluginPath, string? RhinoRoot)
    {
        public static Options Parse(IReadOnlyList<string> args)
        {
            if (args.Count == 0)
                throw new UsageException("A built .gha path is required.");

            string? pluginPath = null;
            string? rhinoRoot = null;
            for (int index = 0; index < args.Count; index++)
            {
                string argument = args[index];
                if (string.Equals(
                    argument,
                    "--rhino-root",
                    StringComparison.OrdinalIgnoreCase))
                {
                    if (++index >= args.Count)
                        throw new UsageException(
                            "--rhino-root requires a directory.");
                    rhinoRoot = args[index];
                    continue;
                }

                if (argument.StartsWith("-", StringComparison.Ordinal))
                    throw new UsageException(
                        $"Unknown option: {argument}");
                if (pluginPath is not null)
                    throw new UsageException(
                        "Only one plugin path may be supplied.");
                pluginPath = argument;
            }

            if (string.IsNullOrWhiteSpace(pluginPath))
                throw new UsageException("A built .gha path is required.");
            return new Options(pluginPath, rhinoRoot);
        }
    }

    private sealed class UsageException : Exception
    {
        public UsageException(string message)
            : base(message)
        {
        }
    }
}
